"name":"advisory_work_state_events_check","validated":true,"definition":"CHECK (ended_at IS NULL OR ended_at >= started_at)"},{"name":"advisory_work_state_events_matter_id_fkey","validated":true,"definition":"FOREIGN KEY (matter_id) REFERENCES advisory_matters(id)"},{"name":"advisory_work_state_events_pkey","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"advisory_work_state_events_work_state_check","validated":true,"definition":"CHECK (work_state = ANY (ARRAY[''working''::text, ''waiting_client''::text, ''waiting_external''::text, ''waiting_internal''::text, ''on_hold''::text]))"}],"rls_enabled":true,"incoming_foreign_keys":[],"effective_grants_before_rls":{"anon":{"delete":false,"insert":false,"select":false,"update":false,"truncate":false},"service_role":{"delete":false,"insert":false,"select":false,"update":false,"truncate":false},"authenticated":{"delete":false,"insert":false,"select":true,"update":false,"truncate":false}}}},"functions":{"advisory076_task_guard()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory076_task_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare m public.advisory_matters%rowtype; changed_link boolean;\nbegin\n select * into m from public.advisory_matters where id=new.advisory_matter_id for update;\n if not found then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n if m.status in (''completed'',''cancelled'') or exists(select 1 from public.advisory_matter_control where matter_id=m.id and closed_at is not null) then raise exception ''ADVISORY_CLOSED''; end if;\n if new.deleted_at is null and new.status not in (''completed'',''cancelled'') and new.stage_id is not null\n and (tg_op=''INSERT'' or new.stage_id is distinct from old.stage_id or new.status is distinct from old.status or old.deleted_at is not null)\n and exists(select 1 from public.advisory_stage_visits where stage_id=new.stage_id and exit_reason=''completed'')\n and not exists(select 1 from public.advisory_stage_visits where stage_id=new.stage_id and kind=''visit'' and exited_at is null)\n then raise exception ''ADVISORY_STAGE_COMPLETED''; end if;\n if tg_op=''UPDATE'' and new.advisory_matter_id<>old.advisory_matter_id then raise exception ''ADVISORY_PARENT_IMMUTABLE''; end if;\n changed_link:=tg_op=''INSERT'' or new.advisory_issue_id is distinct from old.advisory_issue_id or (old.deleted_at is not null and new.deleted_at is null);\n if changed_link and new.advisory_issue_id is not null and not exists(select 1 from public.advisory_issues where id=new.advisory_issue_id and advisory_matter_id=m.id and deleted_at is null for share)\n then raise exception ''ADVISORY_ISSUE_NOT_AVAILABLE''; end if;\n if (tg_op=''INSERT'' or new.client_id is distinct from old.client_id) and new.client_id is not null and new.client_id<>m.client_id then raise exception ''ADVISORY_CLIENT_MISMATCH''; end if;\n if new.stage_id is not null and not exists(select 1 from public.advisory_matter_stages where id=new.stage_id and matter_id=m.id) then raise exception ''ADVISORY_STAGE_MISMATCH''; end if;\n if tg_op=''INSERT'' or new.assignee_user_id is distinct from old.assignee_user_id then perform public.advisory076_check_person(new.assignee_user_id); end if;\n if tg_op=''INSERT'' or new.status is distinct from old.status or new.completed_at is distinct from old.completed_at then\n  if new.status not in (''pending'',''in_progress'',''waiting'',''completed'',''cancelled'') or (new.status=''completed'')<>(new.completed_at is not null) then raise exception ''ADVISORY_TASK_COMPLETION_INVALID''; end if;\n end if;\n if tg_op=''INSERT'' or new.priority is distinct from old.priority then\n  if new.priority not in (''low'',''normal'',''high'',''urgent'') then raise exception ''ADVISORY_PRIORITY_INVALID''; end if;\n end if;\n return new;\nend; $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory076_time_guard()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory076_time_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n if tg_op=''UPDATE'' and new.advisory_matter_id<>old.advisory_matter_id then raise exception ''ADVISORY_PARENT_IMMUTABLE''; end if;\n if new.stage_id is not null and not exists(select 1 from public.advisory_matter_stages where id=new.stage_id and matter_id=new.advisory_matter_id) then raise exception ''ADVISORY_STAGE_MISMATCH''; end if;\n if (tg_op=''INSERT'' or new.advisory_issue_id is distinct from old.advisory_issue_id or (old.deleted_at is not null and new.deleted_at is null)) and new.advisory_issue_id is not null and not exists(select 1 from public.advisory_issues where id=new.advisory_issue_id and advisory_matter_id=new.advisory_matter_id and deleted_at is null for share) then raise exception ''ADVISORY_ISSUE_NOT_AVAILABLE''; end if;\n if (tg_op=''INSERT'' or new.client_id is distinct from old.client_id) and new.client_id is not null and new.client_id is distinct from (select client_id from public.advisory_matters where id=new.advisory_matter_id) then raise exception ''ADVISORY_CLIENT_MISMATCH''; end if;\n if (tg_op=''INSERT'' or new.minutes is distinct from old.minutes) and new.minutes<0 then raise exception ''ADVISORY_TIME_INVALID''; end if;\n return new;\nend; $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory076_allowed(text)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory076_allowed(p_action text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n select exists(select 1 from public.user_profiles p where p.id=auth.uid() and p.active and not p.must_change_password\n and case when p_action in (''read'',''task'',''time'') then p.role in (''admin'',''partner'',''lawyer'',''assistant_lawyer'',''staff'')\n when p_action=''delete'' then p.role in (''admin'',''partner'')\n when p_action=''manage'' then p.role in (''admin'',''partner'',''lawyer'',''assistant_lawyer'') else false end);\n$function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory076_issue_guard()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory076_issue_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n if new.advisory_matter_id<>old.advisory_matter_id then raise exception ''ADVISORY_PARENT_IMMUTABLE''; end if;\n if old.deleted_at is null and new.deleted_at is not null and (\n  exists(select 1 from public.advisory_issue_tasks where advisory_issue_id=old.id and deleted_at is null)\n  or exists(select 1 from public.advisory_time_logs where advisory_issue_id=old.id and deleted_at is null)\n  or exists(select 1 from public.advisory_advice_records where advisory_issue_id=old.id and deleted_at is null)) then\n  raise exception ''ADVISORY_ISSUE_HAS_LIVE_RECORDS'';\n end if;\n return new;\nend; $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory076_template(text)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory076_template(p_key text)\n RETURNS text[]\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\n select case p_key\n when ''contract'' then array[''intake'',''information'',''analysis'',''draft'',''review'',''client_delivery'',''negotiation'',''final'',''close'']\n when ''license'' then array[''intake'',''requirements'',''preparation'',''submission'',''authority_wait'',''amendment'',''result'',''close'']\n when ''opinion'' then array[''brief'',''facts'',''research'',''analysis'',''review'',''opinion_delivery'',''close'']\n when ''negotiation'' then array[''intake'',''facts'',''strategy'',''contact'',''negotiation'',''result'',''close'']\n when ''general'' then array[''intake'',''information'',''analysis'',''execution'',''delivery'',''close'']\n when ''general_advisory'' then array[''intake'',''information'',''analysis'',''execution'',''follow_up'',''close'']\n when ''contract_business_documents'' then array[''intake'',''requirements'',''draft_review'',''internal_review'',''delivery_negotiation'',''final'',''close'']\n when ''legal_analysis_compliance'' then array[''brief'',''facts'',''analysis'',''draft_recommendation'',''review'',''delivery_implementation'',''close'']\n when ''negotiation_pre_litigation'' then array[''intake'',''evidence_position'',''strategy'',''contact'',''negotiation'',''agreement'',''follow_up'',''close'']\n when ''corporate_transactions'' then array[''intake'',''document_review'',''structure_preparation'',''transaction_documents'',''filing_signing'',''follow_up'',''close'']\n when ''government_regulatory'' then array[''legal_route'',''preparation'',''submission_contact'',''clarification_follow_up'',''authority_result'',''close'']\n when ''administrative_challenge'' then array[''order_deadline'',''evidence'',''legal_grounds'',''draft_challenge'',''submission'',''decision_follow_up'',''close'']\n when ''employment_foreign_workforce'' then array[''brief'',''workforce_information'',''analysis'',''documents_guidance'',''execution'',''follow_up'',''close'']\n when ''ip_registration'' then array[''search_review'',''strategy'',''application_preparation'',''submission'',''registrar_review'',''registration'',''close'']\n when ''real_estate_due_diligence'' then array[''review_scope'',''title_documents'',''encumbrances_restrictions'',''risk_analysis'',''report_recommendations'',''close''] end;\n$function$\n","volatility":"i","service_role":false,"authenticated":true},"advisory076_task_activity()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory076_task_activity()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n if auth.uid() is null then raise exception ''ADVISORY_ACTOR_REQUIRED''; end if;\n update public.advisory_matter_control set version=version+1, next_task_id=case when next_task_id=new.id and (new.status in (''completed'',''cancelled'') or new.deleted_at is not null) then null else next_task_id end where matter_id=new.advisory_matter_id;\n insert into public.advisory_matter_activities(matter_id,kind,actor_id,detail) values(new.advisory_matter_id,\n case when tg_op=''INSERT'' then ''task_created'' when new.deleted_at is not null then ''task_deleted'' when new.status=''completed'' and old.status<>''completed'' then ''task_completed'' else ''task_updated'' end,\n auth.uid(),jsonb_build_object(''task_id'',new.id,''title'',new.title,''old'',case when tg_op=''UPDATE'' then to_jsonb(old) end,''new'',to_jsonb(new)));\n insert into public.case_audit_logs(table_name,record_id,action,user_id,old_data,new_data)\n values(''advisory_issue_tasks'',new.id::text,lower(tg_op),auth.uid(),case when tg_op=''UPDATE'' then to_jsonb(old) end,to_jsonb(new));\n return new;\nend; $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory076_lifecycle_guard()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory076_lifecycle_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare c public.advisory_matter_control%rowtype;\nbegin\n if new.status is distinct from old.status then\n  select * into c from public.advisory_matter_control where matter_id=old.id;\n  if found and (case when c.closed_at is null then new.status not in (''active'',''waiting'')\n   else new.status is distinct from case when c.outcome=''cancelled'' then ''cancelled'' else ''completed'' end end)\n  then raise exception ''ADVISORY_USE_CONTROL_LIFECYCLE''; end if;\n end if;\n return new;\nend; $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory_control_read(uuid,jsonb)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_control_read(p_matter_id uuid DEFAULT NULL::uuid, p_query jsonb DEFAULT ''{}''::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare result jsonb; today date:=(current_timestamp at time zone ''Asia/Bangkok'')::date;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n with overdue_items as materialized (select * from public.advisory_overdue_work()),\n ranked_overdue as (\n  select o.*,row_number() over(partition by matter_id order by due_date,source COLLATE \"C\",source_id) position from overdue_items o\n ), overdue as (\n  select matter_id,count(*) overdue_item_count,min(due_date) oldest_overdue_due,max(overdue_days) oldest_overdue_days,\n   coalesce(max(overdue_days) filter(where is_next_action),0) next_action_overdue_days,\n   jsonb_agg(to_jsonb(o)-''matter_id''-''position'' order by due_date,source COLLATE \"C\",source_id) filter(where position<=3) overdue_preview\n  from ranked_overdue o group by matter_id\n ), items as (\n select m.*,coalesce(o.overdue_item_count,0)>0 has_overdue_work,\n coalesce(o.overdue_item_count,0) overdue_item_count,o.oldest_overdue_due,coalesce(o.oldest_overdue_days,0) oldest_overdue_days,\n coalesce(o.next_action_overdue_days,0) next_action_overdue_days,coalesce(o.overdue_preview,''[]''::jsonb) overdue_preview,\n cl.name client_name,coalesce(c.version,0) version,c.work_state,c.closed_at,c.outcome,c.outcome_summary,c.follow_up,c.case_reference,\n c.next_task_id,coalesce(t.title,c.next_action) next_action,coalesce(t.assignee_user_id,c.next_owner_id) next_owner_id,\n coalesce(nullif(np.staff_name,''''),np.full_name,t.assignee_name) next_owner_name,coalesce(t.due_date,c.next_due) next_due,\n lead.user_id lead_id,coalesce(nullif(lp.staff_name,''''),lp.full_name,m.responsible_lawyer) lead_name,\n st.stage_key,st.template_key,v.entered_at,\n (select s->>''name_th'' from public.advisory_journey_snapshots j,lateral jsonb_array_elements(j.definition->''stages'') s where j.matter_id=m.id and s->>''key''=st.stage_key) stage_name_th,\n (select s->>''name_en'' from public.advisory_journey_snapshots j,lateral jsonb_array_elements(j.definition->''stages'') s where j.matter_id=m.id and s->>''key''=st.stage_key) stage_name_en,\n case when v.entered_at is not null then greatest(0,today-(v.entered_at at time zone ''Asia/Bangkok'')::date) end stage_days,\n greatest(0,coalesce((c.closed_at at time zone ''Asia/Bangkok'')::date,today)-coalesce(m.start_date,(m.created_at at time zone ''Asia/Bangkok'')::date)) age_days\n from public.advisory_operational_matters m join public.clients cl on cl.id=m.client_id\n left join overdue o on o.matter_id=m.id\n left join public.advisory_matter_control c on c.matter_id=m.id\n left join public.advisory_issue_tasks t on t.id=c.next_task_id and t.deleted_at is null and t.status in (''pending'',''in_progress'',''waiting'') and t.completed_at is null\n left join public.user_profiles np on np.id=coalesce(t.assignee_user_id,c.next_owner_id)\n left join public.advisory_matter_team lead on lead.matter_id=m.id and lead.team_role=''lead''\n left join public.user_profiles lp on lp.id=lead.user_id\n left join public.advisory_stage_visits v on v.matter_id=m.id and v.kind=''visit'' and v.exited_at is null\n left join public.advisory_matter_stages st on st.id=v.stage_id\n ), filtered as (\n select * from items i where (p_matter_id is null or i.id=p_matter_id)\n and (coalesce(p_query->>''search'','''')='''' or concat_ws('' '',i.matter_no,i.title,i.client_name,i.lead_name) ilike ''%''||(p_query->>''search'')||''%'')\n and (coalesce(p_query->>''client_id'','''')='''' or i.client_id::text=p_query->>''client_id'')\n and (coalesce(p_query->>''type'','''')='''' or i.matter_type=p_query->>''type'')\n and (coalesce(p_query->>''lead'','''')='''' or i.lead_id::text=p_query->>''lead'')\n and (coalesce(p_query->>''state'','''')='''' or i.work_state=p_query->>''state'')\n and case coalesce(p_query->>''tab'',''all'') when ''mine'' then exists(select 1 from public.advisory_matter_team tm where tm.matter_id=i.id and tm.user_id=auth.uid()) or i.next_owner_id=auth.uid()\n when ''overdue'' then i.has_overdue_work\n when ''missing'' then i.closed_at is null and i.next_action is null\n when ''closed'' then i.closed_at is not null else true end\n ), page as (\n select * from filtered order by case when p_query->>''sort''=''due'' then next_due end asc nulls last,created_at desc,id\n limit least(50,greatest(1,coalesce((p_query->>''limit'')::int,20))) offset greatest(0,coalesce((p_query->>''offset'')::int,0))\n ) select jsonb_build_object(''items'',coalesce((select jsonb_agg(to_jsonb(p)) from page p),''[]''),''total'',(select count(*) from filtered),\n ''summary'',(select jsonb_build_object(''open'',count(*) filter(where closed_at is null and status not in (''completed'',''cancelled'')),\n ''overdue'',count(*) filter(where has_overdue_work),''overdue_items'',coalesce(sum(overdue_item_count),0),''waiting'',count(*) filter(where closed_at is null and work_state=''waiting_client''),\n ''closed_week'',count(*) filter(where closed_at>=date_trunc(''week'',current_timestamp at time zone ''Asia/Bangkok'') at time zone ''Asia/Bangkok'')) from items),\n ''permissions'',jsonb_build_object(''manage'',public.advisory076_allowed(''manage''),''task'',public.advisory076_allowed(''task''),''delete'',public.advisory076_allowed(''delete''))) into result;\n if p_matter_id is not null then\n  if jsonb_array_length(result->''items'')<>1 then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n  result:=result||jsonb_build_object(\n   ''journey_path'',(select coalesce(jsonb_agg(to_jsonb(v) order by v.entered_at,v.recorded_at,v.id),''[]''::jsonb) from public.advisory_stage_visits v where v.matter_id=p_matter_id and v.kind=''visit''),\n   ''journey_decisions'',(select coalesce(jsonb_agg(jsonb_build_object(''id'',a.id,''actor_id'',a.actor_id,''occurred_at'',a.occurred_at,''kind'',a.kind,''detail'',a.detail) order by a.occurred_at,a.id),''[]''::jsonb) from public.advisory_matter_activities a where a.matter_id=p_matter_id and a.detail->>''journey_format''=''2''),\n   ''journey_snapshot'',(select to_jsonb(j) from public.advisory_journey_snapshots j where matter_id=p_matter_id),\n   ''state_history'',(select coalesce(jsonb_agg(to_jsonb(x) order by x.started_at desc),''[]'') from (select work_state,started_at,ended_at,reason from public.advisory_work_state_events where matter_id=p_matter_id order by started_at desc limit 10) x),\n   ''team'',(select coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object(''name'',coalesce(nullif(p.staff_name,''''),p.full_name)) order by t.team_role,p.full_name),''[]'') from public.advisory_matter_team t join public.user_profiles p on p.id=t.user_id where t.matter_id=p_matter_id),\n   ''stages'',(select coalesce(jsonb_agg(to_jsonb(s)||coalesce((select element-''key'' from public.advisory_journey_snapshots j, lateral jsonb_array_elements(j.definition->''stages'') element where j.matter_id=s.matter_id and element->>''key''=s.stage_key),''{}''::jsonb)||jsonb_build_object(''visits'',coalesce(v.rows,''[]''),''minutes'',tm.minutes,''elapsed_seconds'',(select sum(extract(epoch from coalesce(exited_at,current_timestamp)-entered_at)) from public.advisory_stage_visits where stage_id=s.id and kind=''visit''),''task_total'',(select count(*) from public.advisory_issue_tasks where stage_id=s.id and deleted_at is null),''task_completed'',(select count(*) from public.advisory_issue_tasks where stage_id=s.id and deleted_at is null and status=''completed''),''unclassified'',tm.unclassified) order by s.position),''[]'')\n    from public.advisory_matter_stages s\n    left join lateral(select jsonb_agg(to_jsonb(x) order by recorded_at desc) rows from (select * from public.advisory_stage_visits where stage_id=s.id order by recorded_at desc limit 20) x) v on true\n    left join lateral(select sum(minutes) minutes,count(*) filter(where stage_id is null) unclassified from public.advisory_time_logs where advisory_matter_id=p_matter_id and stage_id=s.id and deleted_at is null) tm on true where s.matter_id=p_matter_id),\n   ''time'',(select jsonb_build_object(''minutes'',coalesce(sum(minutes),0),''core'',coalesce(sum(minutes) filter(where billable),0),''support'',coalesce(sum(minutes) filter(where not billable),0),''unclassified'',count(*) filter(where stage_id is null)) from public.advisory_time_logs where advisory_matter_id=p_matter_id and deleted_at is null),\n   ''other_matters'',(select coalesce(jsonb_agg(to_jsonb(x)),''[]'') from (select id,matter_no,title,status from public.advisory_operational_matters where client_id=(select client_id from public.advisory_operational_matters where id=p_matter_id) and id<>p_matter_id order by created_at desc limit 5) x));\n end if;\n return result;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory076_check_person(uuid,boolean)":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory076_check_person(p_id uuid, p_lead boolean DEFAULT false)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n if p_id is not null and not exists(select 1 from public.user_profiles where id=p_id and active\n and account_type=''operational'' and assignable and (not p_lead or role in (''admin'',''partner'',''lawyer'',''assistant_lawyer'')) for share)\n then raise exception ''ADVISORY_PERSON_NOT_ASSIGNABLE''; end if;\nend; $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory_control_section(uuid,text,integer,uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_control_section(p_matter_id uuid, p_section text, p_offset integer DEFAULT 0, p_issue_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare tab text; predicate text; ordering text; rows jsonb; total bigint;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n if not exists(select 1 from public.advisory_operational_matters where id=p_matter_id) then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n case p_section\n when ''tasks'' then tab:=''advisory_issue_tasks''; predicate:=''advisory_matter_id=$1 and deleted_at is null and ($3 is null or advisory_issue_id=$3)''; ordering:=''case when status in (''''completed'''',''''cancelled'''') then 1 else 0 end,due_date nulls last,id'';\n when ''deleted_tasks'' then tab:=''advisory_issue_tasks''; predicate:=''advisory_matter_id=$1 and deleted_at is not null and ($3 is null or advisory_issue_id=$3)''; ordering:=''deleted_at desc,id'';\n when ''activity'' then tab:=''advisory_matter_activities''; predicate:=''matter_id=$1''; ordering:=''occurred_at desc,id'';\n when ''deliverables'' then tab:=''advisory_deliverables''; predicate:=''matter_id=$1''; ordering:=''due_date nulls last,id'';\n when ''visits'' then tab:=''advisory_stage_visits''; predicate:=''matter_id=$1''; ordering:=''recorded_at desc,id'';\n when ''states'' then tab:=''advisory_work_state_events''; predicate:=''matter_id=$1''; ordering:=''started_at desc,id'';\n else raise exception ''ADVISORY_SECTION_INVALID''; end case;\n execute format(''select count(*) from public.%I where %s'',tab,predicate) into total using p_matter_id,p_offset,p_issue_id;\n execute format(''select coalesce(jsonb_agg(to_jsonb(t)),''''[]'''') from (select * from public.%I where %s order by %s limit 20 offset $2) t'',tab,predicate,ordering)\n into rows using p_matter_id,greatest(0,p_offset),p_issue_id;\n if p_section=''tasks'' then\n  -- Enrich the existing bounded Task page from the same canonical source once.\n  with overdue as materialized (select * from public.advisory_overdue_work(p_matter_id))\n  select coalesce(jsonb_agg(t.value||jsonb_build_object(''overdue_days'',coalesce(o.overdue_days,0)) order by t.position),''[]''::jsonb)\n  into rows from jsonb_array_elements(rows) with ordinality t(value,position)\n  left join overdue o on o.source=''task'' and o.source_id=(t.value->>''id'')::uuid;\n end if;\n return jsonb_build_object(''items'',rows,''total'',total);\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory_control_write(uuid,text,jsonb,uuid,bigint)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory_control_write(p_matter_id uuid, p_action text, p_payload jsonb, p_request_id uuid, p_expected_version bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare\n actor uuid:=auth.uid(); body jsonb; saved public.advisory_control_requests%rowtype;\n m public.advisory_matters%rowtype; c public.advisory_matter_control%rowtype;\n task public.advisory_issue_tasks%rowtype; d public.advisory_deliverables%rowtype;\n person uuid; item_id uuid; stage public.advisory_matter_stages%rowtype;\n template text; keys text[]; moment timestamptz; result jsonb; event_kind text;\n current_visit public.advisory_stage_visits%rowtype; next_stage public.advisory_matter_stages%rowtype;\n checks jsonb; event_detail jsonb:=''{}''; remaining bigint; old_role text;\n fj jsonb; fj_stage jsonb; fj_skip_current boolean:=false;\n fj2 boolean:=false; chosen jsonb; route_reason text; opened_visit uuid;\nbegin\n if p_request_id is null or p_payload is null or octet_length(p_payload::text)>64000 or jsonb_typeof(p_payload)<>''object'' then raise exception ''ADVISORY_INVALID_INPUT''; end if;\n if not public.advisory076_allowed(case when p_action in (''task_save'',''task_complete'') then ''task''\n  when p_action in (''task_delete'',''task_restore'') then ''delete'' else ''manage'' end) then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n body:=jsonb_build_object(''matter'',p_matter_id,''action'',p_action,''payload'',p_payload,''version'',p_expected_version);\n perform pg_advisory_xact_lock(hashtextextended(''advisory076-request:''||p_request_id::text,0));\n select * into saved from public.advisory_control_requests where request_id=p_request_id;\n if found then\n  if saved.actor_id<>actor or saved.request_body<>body then raise exception ''ADVISORY_RETRY_MISMATCH''; end if;\n  return saved.response;\n end if;\n if p_action=''create'' then\n  if p_matter_id is not null then raise exception ''ADVISORY_INVALID_INPUT''; end if;\n  person:=nullif(p_payload->>''lead_id'','''')::uuid;\n  if person is null or length(btrim(coalesce(p_payload->>''title'',''''))) not between 1 and 500 then raise exception ''ADVISORY_REQUIRED_FIELDS''; end if;\n  perform public.advisory076_check_person(person,true);\n  result:=public.create_advisory_matter_with_number((p_payload->>''client_id'')::uuid,btrim(p_payload->>''title''),\n   coalesce(nullif(p_payload->>''matter_type'',''''),''general_advisory''),''no_retainer'',''active'',null,\n   (clock_timestamp() at time zone ''Asia/Bangkok'')::date,null,null,null,null);\n  p_matter_id:=(result->>''id'')::uuid;\n end if;\n select * into m from public.advisory_matters where id=p_matter_id for update;\n if not found then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n insert into public.advisory_matter_control(matter_id) values(m.id) on conflict do nothing;\n select * into c from public.advisory_matter_control where matter_id=m.id for update;\n if p_action<>''create'' and (p_expected_version is null or p_expected_version<>c.version) then raise exception ''ADVISORY_CHANGED''; end if;\n if (c.closed_at is not null or m.status in (''completed'',''cancelled'')) and p_action<>''reopen'' then raise exception ''ADVISORY_CLOSED''; end if;\n moment:=clock_timestamp();\n event_kind:=p_action;\n select definition into fj from public.advisory_journey_snapshots where matter_id=m.id;\n fj2:=coalesce(fj->''format''=''2''::jsonb,false);\n -- FJ-2 routes are selected only by completion. The established reopen flow\n -- may resume a previously visited stage, but cannot correct a live branch.\n if fj2 and p_action=''stage'' and not exists(select 1 from public.advisory_matter_activities a where a.matter_id=m.id and a.kind=''reopen''\n  and a.occurred_at >= coalesce((select max(coalesce(exited_at,entered_at)) from public.advisory_stage_visits where matter_id=m.id and kind=''visit''),''-infinity''::timestamptz)) then raise exception ''ADVISORY_JOURNEY_USE_ADVANCE''; end if;\n if fj is not null and p_action=''stage'' and (exists(select 1 from public.advisory_stage_visits where matter_id=m.id and kind=''visit'' and exited_at is null) or not exists(select 1 from public.advisory_stage_visits v join public.advisory_matter_stages s on s.id=v.stage_id where v.matter_id=m.id and s.stage_key=p_payload->>''stage_key'' and v.kind=''visit'' and v.exited_at is not null)) then raise exception ''ADVISORY_JOURNEY_USE_ADVANCE''; end if;\n if fj is not null and p_action=''stage_skip'' then\n  select value into fj_stage from jsonb_array_elements(fj->''stages'') where value->>''key''=p_payload->>''stage_key'';\n  if fj_stage is null or (fj_stage->>''required'')::boolean or fj_stage->>''key''=''close'' then raise exception ''ADVISORY_JOURNEY_REQUIRED_STAGE''; end if;\n  if length(btrim(coalesce(p_payload->>''reason'',''''))) not between 1 and 4000 then raise exception ''ADVISORY_JOURNEY_REASON_REQUIRED''; end if;\n  select * into stage from public.advisory_matter_stages where matter_id=m.id and stage_key=p_payload->>''stage_key'';\n  select exists(select 1 from public.advisory_stage_visits where stage_id=stage.id and kind=''visit'' and exited_at is null) into fj_skip_current;\n  if fj2 then\n   -- Optional skip is still a linear waiver, never a branch choice or a way\n   -- to activate a dormant conditional stage. Only the current visit may skip.\n   if not fj_skip_current or jsonb_array_length(fj_stage->''outcomes'')<>1\n    or (fj_stage#>>''{outcomes,0,requires_reason}'')::boolean\n    or fj_stage#>>''{outcomes,0,target}'' is distinct from (select s.stage_key from public.advisory_matter_stages s where s.matter_id=m.id and s.position>stage.position order by s.position limit 1)\n    or exists(select 1 from jsonb_array_elements(fj->''stages'') s where s->>''key''=fj_stage#>>''{outcomes,0,target}'' and (s->>''conditional'')::boolean)\n   then raise exception ''ADVISORY_BRANCH_COMPLETE_REQUIRED''; end if;\n  end if;\n  if exists(select 1 from public.advisory_issue_tasks where stage_id=stage.id and advisory_matter_id=m.id and deleted_at is null and status not in (''completed'',''cancelled'')) then raise exception ''ADVISORY_STAGE_TASKS_OPEN''; end if;\n  if not fj_skip_current and exists(select 1 from public.advisory_issue_tasks where id=c.next_task_id and stage_id=stage.id) then raise exception ''ADVISORY_NEXT_ACTION_RESOLUTION_REQUIRED''; end if;\n end if;\n\n if p_action=''create'' then\n  insert into public.advisory_matter_team values(m.id,person,''lead'');\n  update public.advisory_matter_control set work_state=''working'' where matter_id=m.id;\n  insert into public.advisory_work_state_events(matter_id,work_state,started_at,actor_id) values(m.id,''working'',moment,actor);\n elsif p_action=''team'' then\n  person:=(p_payload->>''user_id'')::uuid;\n  if p_payload->>''role'' not in (''lead'',''co_work'',''assistant'',''qa'') or person is null then raise exception ''ADVISORY_INVALID_INPUT''; end if;\n  if coalesce((p_payload->>''remove'')::boolean,false) then\n   delete from public.advisory_matter_team where matter_id=m.id and user_id=person and team_role=p_payload->>''role'';\n  else\n   perform public.advisory076_check_person(person,p_payload->>''role''=''lead'');\n   if p_payload->>''role''=''lead'' then delete from public.advisory_matter_team where matter_id=m.id and team_role=''lead''; end if;\n   insert into public.advisory_matter_team values(m.id,person,p_payload->>''role'') on conflict do nothing;\n  end if;\n elsif p_action=''team_edit'' then\n  person:=nullif(p_payload->>''user_id'','''')::uuid;\n  old_role:=p_payload->>''previous_role'';\n  if person is null or old_role is null or p_payload->>''role'' is null\n   or old_role not in (''lead'',''co_work'',''assistant'',''qa'')\n   or p_payload->>''role'' not in (''lead'',''co_work'',''assistant'',''qa'') then raise exception ''ADVISORY_INVALID_INPUT''; end if;\n  if not exists(select 1 from public.advisory_matter_team where matter_id=m.id and user_id=person and team_role=old_role) then raise exception ''ADVISORY_TEAM_MEMBER_NOT_FOUND''; end if;\n  if old_role=p_payload->>''role'' then raise exception ''ADVISORY_NO_CHANGE''; end if;\n  perform public.advisory076_check_person(person,p_payload->>''role''=''lead'');\n  if exists(select 1 from public.advisory_matter_team where matter_id=m.id and user_id=person and team_role=p_payload->>''role'') then raise exception ''ADVISORY_TEAM_ROLE_EXISTS''; end if;\n  if p_payload->>''role''=''lead'' and exists(select 1 from public.advisory_matter_team where matter_id=m.id and team_role=''lead'') then raise exception ''ADVISORY_LEAD_EXISTS''; end if;\n  update public.advisory_matter_team set team_role=p_payload->>''role'' where matter_id=m.id and user_id=person and team_role=old_role;\n elsif p_action=''stage_complete'' or fj_skip_current then\n  select * into current_visit from public.advisory_stage_visits where matter_id=m.id and kind=''visit'' and exited_at is null;\n  if not found or current_visit.id is distinct from nullif(p_payload->>''visit_id'','''')::uuid then raise exception ''ADVISORY_CURRENT_STAGE_CHANGED''; end if;\n  select * into stage from public.advisory_matter_stages where id=current_visit.stage_id;\n  if fj2 then\n   if not fj_skip_current then\n   select s into fj_stage from jsonb_array_elements(fj->''stages'') s where s->>''key''=stage.stage_key;\n   if jsonb_array_length(fj_stage->''outcomes'')=1 and nullif(p_payload->>''outcome_key'','''') is null then chosen:=fj_stage#>''{outcomes,0}'';\n   else select o into chosen from jsonb_array_elements(fj_stage->''outcomes'') o where o->>''key''=p_payload->>''outcome_key''; end if;\n   if chosen is null then raise exception ''ADVISORY_OUTCOME_REQUIRED''; end if;\n   route_reason:=nullif(btrim(p_payload->>''outcome_reason''),'''');\n   if length(coalesce(route_reason,''''))>4000 or ((chosen->>''requires_reason'')::boolean and route_reason is null) then raise exception ''ADVISORY_OUTCOME_REASON_REQUIRED''; end if;\n   end if;\n   -- A previous visit''s skip never alters a later loop''s route.\n   select * into next_stage from public.advisory_matter_stages where matter_id=m.id and stage_key=coalesce(chosen->>''target'',fj_stage#>>''{outcomes,0,target}'');\n   if next_stage.id is null then raise exception ''ADVISORY_ROUTE_INVALID''; end if;\n  else\n  select * into next_stage from public.advisory_matter_stages where matter_id=m.id and position>stage.position\n   and not exists(select 1 from public.advisory_stage_visits v where v.stage_id=advisory_matter_stages.id and v.kind=''skip'')\n   order by position limit 1;\n  end if;\n  select count(*) into remaining from public.advisory_issue_tasks where advisory_matter_id=m.id and stage_id=stage.id and deleted_at is null and status not in (''completed'',''cancelled'');\n  if remaining>0 then raise exception ''ADVISORY_STAGE_TASKS_OPEN'' using detail=jsonb_build_object(''count'',remaining)::text; end if;\n  -- A Task in the next operational Stage stays authoritative; all other Next\n  -- Actions need an explicit resolution. Clearing never completes a Task.\n  if c.next_task_id is not null then\n   select * into task from public.advisory_issue_tasks where id=c.next_task_id and advisory_matter_id=m.id;\n  end if;\n  if c.next_action is not null or (c.next_task_id is not null and\n   (task.stage_id is distinct from next_stage.id or next_stage.stage_key=''close'' or next_stage.id is null)) then\n   if coalesce((p_payload->>''resolve_next_action'')::boolean,false) is not true then raise exception ''ADVISORY_NEXT_ACTION_RESOLUTION_REQUIRED''; end if;\n   update public.advisory_matter_control set next_task_id=null,next_action=null,next_owner_id=null,next_due=null where matter_id=m.id;\n  end if;\n  update public.advisory_stage_visits set exited_at=moment,exit_reason=case when fj_skip_current then ''skipped'' else ''completed'' end where id=current_visit.id;\n  if fj_skip_current then insert into public.advisory_stage_visits(matter_id,stage_id,kind,actor_id) values(m.id,stage.id,''skip'',actor); end if;\n  if next_stage.id is not null and next_stage.stage_key<>''close'' then\n   insert into public.advisory_stage_visits(matter_id,stage_id,kind,entered_at,actor_id) values(m.id,next_stage.id,''visit'',moment,actor) returning id into opened_visit;\n  end if;\n  -- ''close'' is a terminal plan marker, not a fabricated visit or lifecycle flip.\n  event_detail:=jsonb_build_object(case when fj_skip_current then ''skipped_stage_id'' else ''completed_stage_id'' end,stage.id,case when fj_skip_current then ''skipped_stage_key'' else ''completed_stage_key'' end,stage.stage_key,\n   ''entered_at'',current_visit.entered_at,''completed_at'',moment,\n   ''next_stage_id'',case when next_stage.stage_key<>''close'' then next_stage.id end,\n   ''next_stage_key'',next_stage.stage_key,''ready_for_closing'',next_stage.id is null or next_stage.stage_key=''close'');\n  if fj2 then\n   event_detail:=event_detail||jsonb_build_object(''journey_format'',2,''actor_name'',(select coalesce(nullif(staff_name,''''),full_name) from public.user_profiles where id=actor),''from_visit_id'',current_visit.id,''to_visit_id'',opened_visit,\n    ''outcome'',chosen,''outcome_reason'',route_reason,\n    ''from_stage'',fj_stage-''outcomes'',''target_stage'',(select s-''outcomes'' from jsonb_array_elements(fj->''stages'') s where s->>''key''=next_stage.stage_key));\n  end if;\n elsif p_action=''work_state'' then\n  if p_payload->>''state'' not in (''working'',''waiting_client'',''waiting_external'',''waiting_internal'',''on_hold'') or p_payload->>''state'' is null then raise exception ''ADVISORY_INVALID_INPUT''; end if;\n  if c.work_state is not distinct from p_payload->>''state'' then raise exception ''ADVISORY_NO_CHANGE''; end if;\n  update public.advisory_work_state_events set ended_at=moment where matter_id=m.id and ended_at is null;\n  insert into public.advisory_work_state_events(matter_id,work_state,started_at,reason,actor_id) values(m.id,p_payload->>''state'',moment,nullif(btrim(p_payload->>''reason''),''''),actor);\n  update public.advisory_matter_control set work_state=p_payload->>''state'' where matter_id=m.id;\n elsif p_action in (''stage'',''stage_skip'') then\n  null; -- Plan creation and transition below, in this same transaction.\n elsif p_action=''next_action'' then\n  item_id:=nullif(p_payload->>''task_id'','''')::uuid;\n  if item_id is not null then\n   select * into task from public.advisory_issue_tasks where id=item_id and advisory_matter_id=m.id and deleted_at is null for update;\n   if not found or task.status not in (''pending'',''in_progress'',''waiting'') or task.completed_at is not null then raise exception ''ADVISORY_TASK_NOT_AVAILABLE''; end if;\n   update public.advisory_matter_control set next_task_id=item_id,next_action=null,next_owner_id=null,next_due=null where matter_id=m.id;\n  else\n   person:=nullif(p_payload->>''owner_id'','''')::uuid;\n   perform public.advisory076_check_person(person);\n   if nullif(btrim(p_payload->>''title''),'''') is null and (person is not null or nullif(p_payload->>''due_date'','''') is not null) then raise exception ''ADVISORY_REQUIRED_FIELDS''; end if;\n   update public.advisory_matter_control set next_task_id=null,next_action=nullif(btrim(p_payload->>''title''),''''),next_owner_id=person,next_due=nullif(p_payload->>''due_date'','''')::date where matter_id=m.id;\n  end if;\n elsif p_action in (''task_save'',''task_complete'',''task_delete'',''task_restore'') then\n  item_id:=nullif(p_payload->>''id'','''')::uuid;\n  if item_id is not null then\n   select * into task from public.advisory_issue_tasks where id=item_id and advisory_matter_id=m.id for update;\n   if not found then raise exception ''ADVISORY_TASK_NOT_FOUND''; end if;\n   if (task.deleted_at is not null)<>(p_action=''task_restore'') then raise exception ''ADVISORY_TASK_NOT_AVAILABLE''; end if;\n  elsif p_action<>''task_save'' then raise exception ''ADVISORY_TASK_NOT_FOUND''; end if;\n  if p_action=''task_complete'' then\n   if task.status in (''completed'',''cancelled'') then raise exception ''ADVISORY_NO_CHANGE''; end if;\n   update public.advisory_issue_tasks set status=''completed'',completed_at=moment,updated_at=moment where id=item_id;\n  elsif p_action=''task_delete'' then\n   update public.advisory_issue_tasks set deleted_at=moment,deleted_by=actor::text,updated_at=moment where id=item_id;\n  elsif p_action=''task_restore'' then\n   update public.advisory_issue_tasks set deleted_at=null,deleted_by=null,updated_at=moment where id=item_id;\n  else\n   if length(btrim(coalesce(p_payload->>''title'',''''))) not between 1 and 500 then raise exception ''ADVISORY_REQUIRED_FIELDS''; end if;\n   person:=nullif(p_payload->>''assignee_user_id'','''')::uuid;\n   if item_id is null or person is distinct from task.assignee_user_id then perform public.advisory076_check_person(person); end if;\n   if item_id is null then\n    insert into public.advisory_issue_tasks(advisory_matter_id,advisory_issue_id,client_id,title,task_type,status,priority,assignee_user_id,stage_id,due_date,completed_at,note)\n    values(m.id,nullif(p_payload->>''issue_id'','''')::uuid,m.client_id,btrim(p_payload->>''title''),coalesce(p_payload->>''task_type'',''general''),coalesce(p_payload->>''status'',''pending''),coalesce(p_payload->>''priority'',''normal''),person,\n     nullif(p_payload->>''stage_id'','''')::uuid,nullif(p_payload->>''due_date'','''')::date,case when p_payload->>''status''=''completed'' then moment end,p_payload->>''note'') returning id into item_id;\n   else\n    update public.advisory_issue_tasks set title=btrim(p_payload->>''title''),\n     advisory_issue_id=case when p_payload ? ''issue_id'' then nullif(p_payload->>''issue_id'','''')::uuid else task.advisory_issue_id end,\n     status=coalesce(p_payload->>''status'',task.status),priority=coalesce(p_payload->>''priority'',task.priority),\n     assignee_user_id=person,stage_id=nullif(p_payload->>''stage_id'','''')::uuid,due_date=nullif(p_payload->>''due_date'','''')::date,\n     completed_at=case when coalesce(p_payload->>''status'',task.status)=task.status then task.completed_at when p_payload->>''status''=''completed'' then moment end,\n     note=p_payload->>''note'',updated_at=moment where id=item_id;\n    -- assignee_name is intentionally never overwritten, even on explicit reassignment.\n   end if;\n  end if;\n  event_kind:=null; -- The table trigger records Task Activity and raw audit once.\n elsif p_action=''deliverable'' then\n  item_id:=nullif(p_payload->>''id'','''')::uuid;\n  person:=nullif(p_payload->>''owner_id'','''')::uuid;\n  if item_id is not null then\n   select * into d from public.advisory_deliverables where id=item_id and matter_id=m.id for update;\n   if not found then raise exception ''ADVISORY_DELIVERABLE_NOT_FOUND''; end if;\n  end if;\n  if item_id is null or person is distinct from d.owner_id then perform public.advisory076_check_person(person); end if;\n  if item_id is null then\n   insert into public.advisory_deliverables(matter_id,title,status,owner_id,due_date,version_label,drive_url)\n   values(m.id,btrim(p_payload->>''title''),coalesce(p_payload->>''status'',''draft''),person,nullif(p_payload->>''due_date'','''')::date,nullif(p_payload->>''version_label'',''''),nullif(p_payload->>''drive_url'','''')) returning id into item_id;\n  else\n   update public.advisory_deliverables set title=btrim(p_payload->>''title''),status=p_payload->>''status'',owner_id=person,due_date=nullif(p_payload->>''due_date'','''')::date,\n   version_label=nullif(p_payload->>''version_label'',''''),drive_url=nullif(p_payload->>''drive_url'',''''),updated_at=moment where id=item_id;\n  end if;\n elsif p_action=''note'' then\n  if length(btrim(coalesce(p_payload->>''text'',''''))) not between 1 and 4000 then raise exception ''ADVISORY_REQUIRED_FIELDS''; end if;\n elsif p_action=''close'' then\n  if nullif(btrim(p_payload->>''summary''),'''') is null or p_payload->>''outcome'' is null then raise exception ''ADVISORY_REQUIRED_FIELDS''; end if;\n  checks:=public.advisory_workflow_checks(m.id);\n  -- No override architecture. An early cancellation/other outcome still reports\n  -- unresolved work; an explicit reason acknowledges it without completing it.\n  if not (checks->>''ready_to_close'')::boolean then\n   if p_payload->>''outcome'' in (''completed'',''agreement'') then\n    raise exception ''ADVISORY_CLOSING_BLOCKED'' using detail=checks::text;\n   elsif nullif(btrim(p_payload->>''unresolved_reason''),'''') is null then\n    raise exception ''ADVISORY_CLOSING_RESOLUTION_REQUIRED'' using detail=checks::text;\n   end if;\n  end if;\n  event_detail:=jsonb_build_object(''closing_checks'',checks,''unresolved_reason'',nullif(btrim(p_payload->>''unresolved_reason''),''''));\n  update public.advisory_stage_visits set exited_at=moment,exit_reason=''closed'' where matter_id=m.id and kind=''visit'' and exited_at is null;\n  update public.advisory_work_state_events set ended_at=moment where matter_id=m.id and ended_at is null;\n  update public.advisory_matter_control set closed_at=moment,outcome=p_payload->>''outcome'',outcome_summary=btrim(p_payload->>''summary''),\n   follow_up=nullif(btrim(p_payload->>''follow_up''),''''),case_reference=nullif(btrim(p_payload->>''case_reference''),''''),next_task_id=null,next_action=null,next_owner_id=null,next_due=null,work_state=null where matter_id=m.id;\n  update public.advisory_matters set status=case when p_payload->>''outcome''=''cancelled'' then ''cancelled'' else ''completed'' end,updated_at=moment where id=m.id;\n elsif p_action=''reopen'' then\n  if (c.closed_at is null and m.status not in (''completed'',''cancelled'')) or nullif(btrim(p_payload->>''reason''),'''') is null then raise exception ''ADVISORY_REQUIRED_FIELDS''; end if;\n  update public.advisory_matter_control set closed_at=null,outcome=null,outcome_summary=null,follow_up=null,case_reference=null,work_state=''working'' where matter_id=m.id;\n  update public.advisory_matters set status=''active'',updated_at=moment where id=m.id;\n  insert into public.advisory_work_state_events(matter_id,work_state,started_at,reason,actor_id) values(m.id,''working'',moment,p_payload->>''reason'',actor);\n  -- Previous closing evidence stays in Activity; reopening does not fake a current visit.\n else raise exception ''ADVISORY_ACTION_INVALID''; end if;\n\n if p_action=''create'' then\n  perform public.advisory086_snapshot(m.id,m.matter_type,nullif(p_payload->>''variant_id'','''')::uuid,nullif(p_payload->>''journey_version_id'','''')::uuid);\n end if;\n if p_action in (''create'',''stage'',''stage_skip'') and not fj_skip_current then\n  if not exists(select 1 from public.advisory_matter_stages where matter_id=m.id) then\n   template:=coalesce(nullif(p_payload->>''template'',''''),case m.matter_type when ''contract_review'' then ''contract'' when ''legal_opinion'' then ''opinion'' when ''license_regulatory'' then ''license'' when ''negotiation'' then ''negotiation'' else ''general'' end);\n   keys:=public.advisory076_template(template);\n   if keys is null then raise exception ''ADVISORY_TEMPLATE_INVALID''; end if;\n   insert into public.advisory_matter_stages(matter_id,template_key,stage_key,position) select m.id,template,k,n-1 from unnest(keys) with ordinality s(k,n);\n  end if;\n  if p_action=''create'' then\n   -- Start only this newly created Matter, using its actual ordered plan.\n   select * into stage from public.advisory_matter_stages\n    where matter_id=m.id and stage_key<>''close'' order by position asc limit 1;\n   if not found then raise exception ''ADVISORY_INITIAL_STAGE_NOT_FOUND''; end if;\n   insert into public.advisory_stage_visits(matter_id,stage_id,kind,entered_at,actor_id)\n    values(m.id,stage.id,''visit'',moment,actor)\n    returning jsonb_build_object(''initial_stage'',jsonb_build_object(\n     ''stage_id'',stage.id,''stage_key'',stage.stage_key,''template_key'',stage.template_key,\n     ''visit_id'',id,''kind'',kind,''entered_at'',entered_at)) into event_detail;\n  elsif p_action in (''stage'',''stage_skip'') then\n   select * into stage from public.advisory_matter_stages where matter_id=m.id and stage_key=p_payload->>''stage_key'';\n   if not found then raise exception ''ADVISORY_STAGE_NOT_FOUND''; end if;\n   if stage.stage_key=''close'' then raise exception ''ADVISORY_USE_CLOSE''; end if;\n   if exists(select 1 from public.advisory_stage_visits where stage_id=stage.id and kind=''visit'' and exited_at is null) then raise exception ''ADVISORY_STAGE_ALREADY_CURRENT''; end if;\n   if p_action=''stage'' then\n    select * into current_visit from public.advisory_stage_visits where matter_id=m.id and kind=''visit'' and exited_at is null;\n    if found then\n     -- Old manual stage selection cannot bypass the normal Task/Next Action guard.\n     if exists(select 1 from public.advisory_issue_tasks where advisory_matter_id=m.id and stage_id=current_visit.stage_id and deleted_at is null and status not in (''completed'',''cancelled'')) then raise exception ''ADVISORY_STAGE_TASKS_OPEN''; end if;\n     if c.next_task_id is not null or c.next_action is not null then raise exception ''ADVISORY_NEXT_ACTION_RESOLUTION_REQUIRED''; end if;\n    end if;\n   end if;\n   if p_action=''stage_skip'' then\n    if exists(select 1 from public.advisory_stage_visits where stage_id=stage.id) then raise exception ''ADVISORY_STAGE_HAS_HISTORY''; end if;\n    insert into public.advisory_stage_visits(matter_id,stage_id,kind,actor_id) values(m.id,stage.id,''skip'',actor);\n   else\n    update public.advisory_stage_visits set exited_at=moment,exit_reason=''transition'' where matter_id=m.id and kind=''visit'' and exited_at is null;\n    insert into public.advisory_stage_visits(matter_id,stage_id,kind,entered_at,actor_id) values(m.id,stage.id,''visit'',moment,actor);\n   end if;\n  end if;\n end if;\n if event_kind is not null then\n  insert into public.advisory_matter_activities(matter_id,kind,actor_id,detail) values(m.id,event_kind,actor,\n   jsonb_build_object(''input'',p_payload,''previous_control'',to_jsonb(c),''previous_lifecycle'',m.status,''previous_deliverable'',case when p_action=''deliverable'' then to_jsonb(d) end,''item_id'',item_id)||event_detail);\n end if;\n update public.advisory_matter_control set version=version+1 where matter_id=m.id returning jsonb_build_object(''matter_id'',m.id,''version'',version,''item_id'',item_id) into result;\n if p_action=''stage_complete'' or fj_skip_current then result:=result||event_detail; end if;\n insert into public.advisory_control_requests(request_id,actor_id,request_body,response) values(p_request_id,actor,body,result);\n return result;\nend; $function$\n","volatility":"v","service_role":false,"authenticated":true},"advisory_workflow_checks(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_workflow_checks(p_matter_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare m public.advisory_matters%rowtype; c public.advisory_matter_control%rowtype;\n visit public.advisory_stage_visits%rowtype; stage public.advisory_matter_stages%rowtype;\n open_tasks bigint; pending_deliverables bigint; uncompleted_stages bigint; stage_open_tasks bigint;\n has_next boolean; result jsonb; fj jsonb; options jsonb;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n select * into m from public.advisory_operational_matters where id=p_matter_id;\n if not found then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n select * into c from public.advisory_matter_control where matter_id=m.id;\n select * into visit from public.advisory_stage_visits where matter_id=m.id and kind=''visit'' and exited_at is null;\n select * into stage from public.advisory_matter_stages where id=visit.stage_id;\n select count(*) into open_tasks from public.advisory_issue_tasks where advisory_matter_id=m.id and deleted_at is null and status not in (''completed'',''cancelled'');\n select count(*) into stage_open_tasks from public.advisory_issue_tasks where advisory_matter_id=m.id and stage_id=stage.id and deleted_at is null and status not in (''completed'',''cancelled'');\n select count(*) into pending_deliverables from public.advisory_deliverables where matter_id=m.id and status not in (''delivered'',''cancelled'');\n select count(*) into uncompleted_stages from public.advisory_matter_stages s where s.matter_id=m.id and s.stage_key<>''close''\n and not exists(select 1 from public.advisory_stage_visits v where v.stage_id=s.id and\n  (v.kind=''skip'' or (v.kind=''visit'' and v.exited_at is not null)));\n select definition into fj from public.advisory_journey_snapshots where matter_id=m.id;\n if fj->''format''=''2''::jsonb then\n  select s->''outcomes'' into options from jsonb_array_elements(fj->''stages'') s where s->>''key''=stage.stage_key;\n  -- Only the actual chosen route affects closing; unchosen branches are not\n  -- incomplete work, and no skip/history is fabricated for them.\n  uncompleted_stages:=case when visit.id is null and exists(\n   select 1 from public.advisory_matter_activities a where a.matter_id=m.id and a.kind in (''stage_complete'',''stage_skip'')\n    and a.detail->>''journey_format''=''2'' and a.detail->>''next_stage_key''=''close''\n    and a.detail->>''from_visit_id''=(select v.id::text from public.advisory_stage_visits v where v.matter_id=m.id and v.kind=''visit'' order by v.entered_at desc,v.recorded_at desc,v.id desc limit 1)\n  ) then 0 else 1 end;\n end if;\n has_next:=c.next_task_id is not null or c.next_action is not null;\n result:=jsonb_build_object(''matter_id'',m.id,''version'',coalesce(c.version,0),''lifecycle'',m.status,\n  ''closed'',c.closed_at is not null or m.status in (''completed'',''cancelled''),\n  ''current_visit_id'',visit.id,''current_stage_id'',stage.id,''current_stage_key'',stage.stage_key,\n  ''current_stage_open_tasks'',stage_open_tasks,''open_tasks'',open_tasks,''has_next_action'',has_next,\n  ''pending_deliverables'',pending_deliverables,''uncompleted_stages'',uncompleted_stages,\n  ''stage_ready'',visit.id is null and uncompleted_stages=0,\n  ''legacy_without_plan'',not exists(select 1 from public.advisory_matter_stages where matter_id=m.id),\n  ''ready_to_close'',open_tasks=0 and not has_next and pending_deliverables=0 and visit.id is null and uncompleted_stages=0);\n if fj->''format''=''2''::jsonb then result:=result||jsonb_build_object(''journey_format'',2,''outcomes'',coalesce(options,''[]''::jsonb),\n  ''route_stages'',(select jsonb_agg(s-''outcomes'' order by n) from jsonb_array_elements(fj->''stages'') with ordinality x(s,n))); end if;\n return result;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory_overdue_work(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_overdue_work(p_matter_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(matter_id uuid, source text, source_id uuid, title text, assignee_user_id uuid, assignee_name text, due_date date, overdue_days integer, is_next_action boolean)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare today date:=(current_timestamp at time zone ''Asia/Bangkok'')::date;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n -- Invoker/RLS remains authoritative. Identity is (source, source_id), never title.\n return query\n with open_matters as materialized (\n  select m.id,c.next_task_id,c.next_action,c.next_owner_id,c.next_due\n  from public.advisory_operational_matters m left join public.advisory_matter_control c on c.matter_id=m.id\n  where (p_matter_id is null or m.id=p_matter_id)\n   and m.status not in (''completed'',''cancelled'') and c.closed_at is null\n )\n select m.id,''task''::text,t.id,t.title,t.assignee_user_id,\n  coalesce(nullif(p.staff_name,''''),p.full_name,t.assignee_name),t.due_date,today-t.due_date,\n  coalesce(m.next_task_id=t.id,false)\n from open_matters m join public.advisory_issue_tasks t on t.advisory_matter_id=m.id\n left join public.user_profiles p on p.id=t.assignee_user_id\n where t.deleted_at is null and t.completed_at is null\n  and t.status in (''pending'',''in_progress'',''waiting'') and t.due_date<today\n union all\n select m.id,''next_action''::text,m.id,m.next_action,m.next_owner_id,\n  coalesce(nullif(p.staff_name,''''),p.full_name),m.next_due,today-m.next_due,true\n from open_matters m left join public.user_profiles p on p.id=m.next_owner_id\n where m.next_task_id is null and nullif(btrim(m.next_action),'''') is not null and m.next_due<today;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true}}}'::jsonb,'old_catalog',encode(sha256(convert_to((state->'catalog')::text,'UTF8')),'hex')='0d9fbb5a5e1c05da206abf934753a5318de35e8cd7ce1463216e4b28a0c70491','journey',j='{"tables":{"advisory_journey_requests":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":true,"owner":"postgres","columns":[{"acl":null,"name":"request_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"actor_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"body","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"response","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"previous_state","type":"jsonb","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"resulting_state","type":"jsonb","default":null,"identity":"","not_null":false,"generated":""},{"acl":null,"name":"recorded_at","type":"timestamp with time zone","default":"clock_timestamp()","identity":"","not_null":true,"generated":""}],"indexes":["CREATE UNIQUE INDEX advisory_journey_requests_pkey ON public.advisory_journey_requests USING btree (request_id)"],"policies":[{"name":"advisory086_read","check":null,"roles":["authenticated"],"using":"advisory086_admin()","command":"r","permissive":true}],"triggers":[{"enabled":"O","definition":"CREATE TRIGGER advisory086_request_immutable BEFORE DELETE OR UPDATE ON advisory_journey_requests FOR EACH ROW EXECUTE FUNCTION advisory086_immutable()"}],"force_rls":false,"constraints":[{"name":"advisory_journey_requests_actor_id_fkey","validated":true,"definition":"FOREIGN KEY (actor_id) REFERENCES user_profiles(id)"},{"name":"advisory_journey_requests_pkey","validated":true,"definition":"PRIMARY KEY (request_id)"}]},"advisory_journey_variants":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":true,"owner":"postgres","columns":[{"acl":null,"name":"id","type":"uuid","default":"gen_random_uuid()","identity":"","not_null":true,"generated":""},{"acl":null,"name":"family_key","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"active","type":"boolean","default":"true","identity":"","not_null":true,"generated":""},{"acl":null,"name":"is_default","type":"boolean","default":"false","identity":"","not_null":true,"generated":""},{"acl":null,"name":"revision","type":"bigint","default":"1","identity":"","not_null":true,"generated":""},{"acl":null,"name":"created_at","type":"timestamp with time zone","default":"clock_timestamp()","identity":"","not_null":true,"generated":""}],"indexes":["CREATE UNIQUE INDEX advisory086_one_default ON public.advisory_journey_variants USING btree (family_key) WHERE is_default","CREATE UNIQUE INDEX advisory_journey_variants_pkey ON public.advisory_journey_variants USING btree (id)"],"policies":[{"name":"advisory086_read","check":null,"roles":["authenticated"],"using":"(advisory076_allowed(''read''::text) AND (active OR advisory086_admin()))","command":"r","permissive":true}],"triggers":[],"force_rls":false,"constraints":[{"name":"advisory_journey_variants_check","validated":true,"definition":"CHECK (NOT is_default OR active)"},{"name":"advisory_journey_variants_pkey","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"advisory_journey_variants_revision_check","validated":true,"definition":"CHECK (revision > 0)"}]},"advisory_journey_versions":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":true,"owner":"postgres","columns":[{"acl":null,"name":"id","type":"uuid","default":"gen_random_uuid()","identity":"","not_null":true,"generated":""},{"acl":null,"name":"variant_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"version","type":"integer","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"definition","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"created_at","type":"timestamp with time zone","default":"clock_timestamp()","identity":"","not_null":true,"generated":""},{"acl":null,"name":"created_by","type":"uuid","default":null,"identity":"","not_null":false,"generated":""}],"indexes":["CREATE UNIQUE INDEX advisory_journey_versions_pkey ON public.advisory_journey_versions USING btree (id)","CREATE UNIQUE INDEX advisory_journey_versions_variant_id_version_key ON public.advisory_journey_versions USING btree (variant_id, version)"],"policies":[{"name":"advisory086_read","check":null,"roles":["authenticated"],"using":"advisory086_admin()","command":"r","permissive":true}],"triggers":[{"enabled":"O","definition":"CREATE TRIGGER advisory086_version_immutable BEFORE DELETE OR UPDATE ON advisory_journey_versions FOR EACH ROW EXECUTE FUNCTION advisory086_immutable()"}],"force_rls":false,"constraints":[{"name":"advisory_journey_versions_created_by_fkey","validated":true,"definition":"FOREIGN KEY (created_by) REFERENCES user_profiles(id)"},{"name":"advisory_journey_versions_definition_check","validated":true,"definition":"CHECK (advisory087_valid_version(definition))"},{"name":"advisory_journey_versions_pkey","validated":true,"definition":"PRIMARY KEY (id)"},{"name":"advisory_journey_versions_variant_id_fkey","validated":true,"definition":"FOREIGN KEY (variant_id) REFERENCES advisory_journey_variants(id) ON DELETE RESTRICT"},{"name":"advisory_journey_versions_variant_id_version_key","validated":true,"definition":"UNIQUE (variant_id, version)"},{"name":"advisory_journey_versions_version_check","validated":true,"definition":"CHECK (version > 0)"}]},"advisory_journey_snapshots":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":true,"owner":"postgres","columns":[{"acl":null,"name":"matter_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"version_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"family_key","type":"text","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"variant_id","type":"uuid","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"version","type":"integer","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"definition","type":"jsonb","default":null,"identity":"","not_null":true,"generated":""},{"acl":null,"name":"captured_at","type":"timestamp with time zone","default":"clock_timestamp()","identity":"","not_null":true,"generated":""},{"acl":null,"name":"captured_by","type":"uuid","default":null,"identity":"","not_null":true,"generated":""}],"indexes":["CREATE UNIQUE INDEX advisory_journey_snapshots_pkey ON public.advisory_journey_snapshots USING btree (matter_id)"],"policies":[{"name":"advisory086_read","check":null,"roles":["authenticated"],"using":"advisory076_allowed(''read''::text)","command":"r","permissive":true}],"triggers":[{"enabled":"O","definition":"CREATE TRIGGER advisory086_snapshot_immutable BEFORE DELETE OR UPDATE ON advisory_journey_snapshots FOR EACH ROW EXECUTE FUNCTION advisory086_immutable()"}],"force_rls":false,"constraints":[{"name":"advisory_journey_snapshots_captured_by_fkey","validated":true,"definition":"FOREIGN KEY (captured_by) REFERENCES user_profiles(id)"},{"name":"advisory_journey_snapshots_definition_check","validated":true,"definition":"CHECK (advisory087_valid_version(definition))"},{"name":"advisory_journey_snapshots_matter_id_fkey","validated":true,"definition":"FOREIGN KEY (matter_id) REFERENCES advisory_matters(id) ON DELETE RESTRICT"},{"name":"advisory_journey_snapshots_pkey","validated":true,"definition":"PRIMARY KEY (matter_id)"},{"name":"advisory_journey_snapshots_variant_id_fkey","validated":true,"definition":"FOREIGN KEY (variant_id) REFERENCES advisory_journey_variants(id) ON DELETE RESTRICT"},{"name":"advisory_journey_snapshots_version_id_fkey","validated":true,"definition":"FOREIGN KEY (version_id) REFERENCES advisory_journey_versions(id) ON DELETE RESTRICT"}]}},"functions":{"advisory086_admin()":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":true},"definition":"CREATE OR REPLACE FUNCTION public.advisory086_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n select exists(select 1 from public.user_profiles where id=auth.uid() and role=''admin'' and active and not must_change_password);\n$function$\n","volatility":"s","security_definer":true},"advisory086_immutable()":{"acl":"{postgres=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":false},"definition":"CREATE OR REPLACE FUNCTION public.advisory086_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''public''\nAS $function$\nbegin raise exception ''ADVISORY_JOURNEY_IMMUTABLE''; end; $function$\n","volatility":"v","security_definer":false},"advisory086_family(p_type text)":{"acl":"{postgres=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":false},"definition":"CREATE OR REPLACE FUNCTION public.advisory086_family(p_type text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$ select case p_type when ''general_advisory'' then ''general_advisory'' when ''contract_business_documents'' then ''contract_business_documents'' when ''legal_opinion'' then ''legal_analysis_compliance'' when ''negotiation'' then ''negotiation_pre_litigation'' when ''corporate_registration'' then ''corporate_transactions'' when ''license_regulatory'' then ''government_regulatory'' when ''government_coordination'' then ''government_regulatory'' when ''administrative_challenge'' then ''administrative_challenge'' when ''employment_hr'' then ''employment_foreign_workforce'' when ''intellectual_property'' then ''ip_registration'' when ''compliance'' then ''legal_analysis_compliance'' when ''data_privacy'' then ''legal_analysis_compliance'' when ''real_estate_review'' then ''real_estate_due_diligence'' when ''pre_litigation_debt'' then ''negotiation_pre_litigation'' when ''transactions_review'' then ''corporate_transactions'' when ''foreign_investment'' then ''government_regulatory'' when ''foreign_workforce'' then ''employment_foreign_workforce'' when ''other'' then ''general_advisory'' end; $function$\n","volatility":"i","security_definer":false},"advisory086_valid_version(p jsonb)":{"acl":"{postgres=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":false},"definition":"CREATE OR REPLACE FUNCTION public.advisory086_valid_version(p jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare s jsonb; n integer; keys text[]:=''{}'';\nbegin\n if jsonb_typeof(p) is distinct from ''object'' or p-''name_th''-''name_en''-''stages''<>''{}'' then return false; end if;\n if jsonb_typeof(p->''name_th'') is distinct from ''string'' or jsonb_typeof(p->''name_en'') is distinct from ''string''\n or length(btrim(coalesce(p->>''name_th'',''''))) not between 1 and 160 or length(btrim(coalesce(p->>''name_en'',''''))) not between 1 and 160\n or jsonb_typeof(p->''stages'') is distinct from ''array'' then return false; end if;\n n:=jsonb_array_length(p->''stages''); if n not between 2 and 20 then return false; end if;\n for s in select value from jsonb_array_elements(p->''stages'') loop\n  if jsonb_typeof(s) is distinct from ''object'' or s-''key''-''name_th''-''name_en''-''required''<>''{}''\n  or jsonb_typeof(s->''key'') is distinct from ''string'' or (s->>''key'')!~''^[a-z][a-z0-9_]{1,59}$''\n  or jsonb_typeof(s->''required'') is distinct from ''boolean''\n  or jsonb_typeof(s->''name_th'') is distinct from ''string'' or jsonb_typeof(s->''name_en'') is distinct from ''string''\n  or length(btrim(coalesce(s->>''name_th'',''''))) not between 1 and 160 or length(btrim(coalesce(s->>''name_en'',''''))) not between 1 and 160\n  or (s->>''key'')=any(keys) then return false; end if;\n  keys:=array_append(keys,s->>''key'');\n end loop;\n return p#>>''{stages,0,key}''<>''close'' and (p#>>''{stages,0,required}'')::boolean\n and p#>>array[''stages'',(n-1)::text,''key'']=''close'' and (p#>>array[''stages'',(n-1)::text,''required''])::boolean\n and array_position(keys,''close'')=n;\nend; $function$\n","volatility":"i","security_definer":false},"advisory087_valid_version(p jsonb)":{"acl":"{postgres=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":false},"definition":"CREATE OR REPLACE FUNCTION public.advisory087_valid_version(p jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$\ndeclare s jsonb; o jsonb; keys text[]:=''{}''; outcome_keys text[]; reachable text[]; closing text[]; changed boolean; n integer;\nbegin\n if public.advisory086_valid_version(p) then return true; end if;\n if jsonb_typeof(p) is distinct from ''object'' or p-''format''-''name_th''-''name_en''-''stages''<>''{}'' or p->''format'' is distinct from ''2''::jsonb\n or jsonb_typeof(p->''stages'') is distinct from ''array'' then return false; end if;\n if jsonb_typeof(p->''name_th'') is distinct from ''string'' or jsonb_typeof(p->''name_en'') is distinct from ''string''\n or length(btrim(coalesce(p->>''name_th'',''''))) not between 1 and 160 or length(btrim(coalesce(p->>''name_en'',''''))) not between 1 and 160 then return false; end if;\n n:=jsonb_array_length(p->''stages''); if n not between 2 and 20 then return false; end if;\n for s in select value from jsonb_array_elements(p->''stages'') loop\n  if jsonb_typeof(s) is distinct from ''object'' or s-''key''-''name_th''-''name_en''-''required''-''conditional''-''outcomes''<>''{}''\n  or jsonb_typeof(s->''key'') is distinct from ''string'' or s->>''key''!~''^[a-z][a-z0-9_]{1,59}$'' or (s->>''key'')=any(keys)\n  or jsonb_typeof(s->''required'') is distinct from ''boolean'' or jsonb_typeof(s->''conditional'') is distinct from ''boolean''\n  or jsonb_typeof(s->''name_th'') is distinct from ''string'' or jsonb_typeof(s->''name_en'') is distinct from ''string''\n  or length(btrim(coalesce(s->>''name_th'',''''))) not between 1 and 160 or length(btrim(coalesce(s->>''name_en'',''''))) not between 1 and 160\n  or jsonb_typeof(s->''outcomes'') is distinct from ''array'' then return false; end if;\n  if (s->>''key''=''close'' and s->''outcomes''<>''[]'') or (s->>''key''<>''close'' and jsonb_array_length(s->''outcomes'') not between 1 and 8) then return false; end if;\n  keys:=array_append(keys,s->>''key''); outcome_keys:=''{}'';\n  for o in select value from jsonb_array_elements(s->''outcomes'') loop\n   if jsonb_typeof(o) is distinct from ''object'' or o-''key''-''name_th''-''name_en''-''target''-''requires_reason''<>''{}''\n   or jsonb_typeof(o->''key'') is distinct from ''string'' or o->>''key''!~''^[a-z][a-z0-9_]{1,59}$'' or (o->>''key'')=any(outcome_keys)\n   or jsonb_typeof(o->''target'') is distinct from ''string'' or jsonb_typeof(o->''requires_reason'') is distinct from ''boolean''\n   or jsonb_typeof(o->''name_th'') is distinct from ''string'' or jsonb_typeof(o->''name_en'') is distinct from ''string''\n   or length(btrim(coalesce(o->>''name_th'',''''))) not between 1 and 160 or length(btrim(coalesce(o->>''name_en'',''''))) not between 1 and 160 then return false; end if;\n   outcome_keys:=array_append(outcome_keys,o->>''key'');\n  end loop;\n end loop;\n if p#>>''{stages,0,key}''=''close'' or not (p#>>''{stages,0,required}'')::boolean or (p#>>''{stages,0,conditional}'')::boolean\n or p#>>array[''stages'',(n-1)::text,''key'']<>''close'' or not (p#>>array[''stages'',(n-1)::text,''required''])::boolean\n or (p#>>array[''stages'',(n-1)::text,''conditional''])::boolean or array_position(keys,''close'')<>n then return false; end if;\n if exists(select 1 from jsonb_array_elements(p->''stages'') st,lateral jsonb_array_elements(st->''outcomes'') ot where not (ot->>''target'')=any(keys)) then return false; end if;\n -- Every stage is reachable from intake and has a possible route to close.\n -- Loops are legal; a disconnected stage or a trapped cycle is not publishable.\n reachable:=array[p#>>''{stages,0,key}'']; closing:=array[''close''];\n loop\n  changed:=false;\n  for s in select value from jsonb_array_elements(p->''stages'') loop\n   for o in select value from jsonb_array_elements(s->''outcomes'') loop\n    if (s->>''key'')=any(reachable) and not (o->>''target'')=any(reachable) then reachable:=array_append(reachable,o->>''target''); changed:=true; end if;\n    if (o->>''target'')=any(closing) and not (s->>''key'')=any(closing) then closing:=array_append(closing,s->>''key''); changed:=true; end if;\n   end loop;\n  end loop;\n  exit when not changed;\n end loop;\n return keys<@reachable and keys<@closing;\nend; $function$\n","volatility":"i","security_definer":false},"advisory086_family_valid(p_family text)":{"acl":"{postgres=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":false},"definition":"CREATE OR REPLACE FUNCTION public.advisory086_family_valid(p_family text)\n RETURNS boolean\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''public''\nAS $function$ select coalesce(p_family=any(array[''general_advisory'',''contract_business_documents'',''legal_analysis_compliance'',''negotiation_pre_litigation'',''corporate_transactions'',''government_regulatory'',''administrative_challenge'',''employment_foreign_workforce'',''ip_registration'',''real_estate_due_diligence'']),false); $function$\n","volatility":"i","security_definer":false},"advisory_journey_catalog(p_family text)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":true},"definition":"CREATE OR REPLACE FUNCTION public.advisory_journey_catalog(p_family text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n return jsonb_build_object(''manage'',public.advisory086_admin(),''variants'',coalesce((\n  select jsonb_agg(to_jsonb(v)||jsonb_build_object(''version_id'',d.id,''version'',d.version,''definition'',d.definition) order by v.family_key collate \"C\",v.is_default desc,v.id)\n  from public.advisory_journey_variants v cross join lateral(select * from public.advisory_journey_versions where variant_id=v.id order by version desc limit 1) d\n  where (p_family is null or v.family_key=p_family) and (v.active or public.advisory086_admin())\n ),''[]''::jsonb));\nend; $function$\n","volatility":"s","security_definer":true},"advisory086_snapshot(p_matter uuid, p_type text, p_variant uuid, p_version uuid)":{"acl":"{postgres=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":false},"definition":"CREATE OR REPLACE FUNCTION public.advisory086_snapshot(p_matter uuid, p_type text, p_variant uuid, p_version uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare family text:=public.advisory086_family(p_type); v public.advisory_journey_variants%rowtype; d public.advisory_journey_versions%rowtype;\nbegin\n if family is null then raise exception ''ADVISORY_JOURNEY_INVALID''; end if;\n perform pg_advisory_xact_lock_shared(hashtextextended(''advisory086-family:''||family,0));\n select * into v from public.advisory_journey_variants where family_key=family and active and (case when p_variant is null then is_default else id=p_variant end);\n if not found then raise exception ''ADVISORY_JOURNEY_UNAVAILABLE''; end if;\n select * into d from public.advisory_journey_versions where variant_id=v.id order by version desc limit 1;\n if not found or (p_version is not null and p_version<>d.id) then raise exception ''ADVISORY_JOURNEY_CHANGED''; end if;\n insert into public.advisory_journey_snapshots(matter_id,version_id,family_key,variant_id,version,definition,captured_by) values(p_matter,d.id,family,v.id,d.version,d.definition,auth.uid());\n insert into public.advisory_matter_stages(matter_id,template_key,stage_key,position)\n select p_matter,family,s->>''key'',n-1 from jsonb_array_elements(d.definition->''stages'') with ordinality x(s,n);\nend; $function$\n","volatility":"v","security_definer":true},"advisory_journey_manage(p_id uuid, p_action text, p_payload jsonb, p_request_id uuid, p_expected_revision bigint)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","owner":"postgres","config":["search_path=public"],"execute":{"anon":false,"service_role":false,"authenticated":true},"definition":"CREATE OR REPLACE FUNCTION public.advisory_journey_manage(p_id uuid, p_action text, p_payload jsonb, p_request_id uuid, p_expected_revision bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\ndeclare actor uuid:=auth.uid(); body jsonb; saved public.advisory_journey_requests%rowtype;\n v public.advisory_journey_variants%rowtype; family text; before_state jsonb; result jsonb; ver integer;\nbegin\n if not public.advisory086_admin() then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n if p_request_id is null or jsonb_typeof(p_payload) is distinct from ''object'' or octet_length(p_payload::text)>32000 then raise exception ''ADVISORY_INVALID_INPUT''; end if;\n body:=jsonb_build_object(''id'',p_id,''action'',p_action,''payload'',p_payload,''revision'',p_expected_revision);\n perform pg_advisory_xact_lock(hashtextextended(''advisory086-request:''||p_request_id,0));\n select * into saved from public.advisory_journey_requests where request_id=p_request_id;\n if found then if saved.actor_id<>actor or saved.body<>body then raise exception ''ADVISORY_RETRY_MISMATCH''; end if; return saved.response; end if;\n if p_action=''create'' then\n  if p_id is not null or p_payload-''family_key''-''definition''<>''{}'' then raise exception ''ADVISORY_INVALID_INPUT''; end if;\n  family:=p_payload->>''family_key'';\n else select family_key into family from public.advisory_journey_variants where id=p_id; end if;\n if family is null or not public.advisory086_family_valid(family) then raise exception ''ADVISORY_JOURNEY_INVALID''; end if;\n perform pg_advisory_xact_lock(hashtextextended(''advisory086-family:''||family,0));\n if p_action=''create'' then\n  insert into public.advisory_journey_variants(family_key,is_default) values(family,not exists(select 1 from public.advisory_journey_variants where family_key=family and active)) returning * into v;\n else\n  select * into v from public.advisory_journey_variants where id=p_id for update;\n  if p_expected_revision is distinct from v.revision then raise exception ''ADVISORY_CHANGED''; end if;\n  before_state:=to_jsonb(v);\n end if;\n if p_action in (''create'',''publish'') then\n  if (p_action=''publish'' and p_payload-''definition''<>''{}'') or not public.advisory087_valid_version(p_payload->''definition'') then raise exception ''ADVISORY_JOURNEY_INVALID''; end if;\n  select coalesce(max(version),0)+1 into ver from public.advisory_journey_versions where variant_id=v.id;\n  insert into public.advisory_journey_versions(variant_id,version,definition,created_by) values(v.id,ver,p_payload->''definition'',actor);\n elsif p_action=''configure'' then\n  if p_payload-''active''-''is_default''<>''{}'' or jsonb_typeof(p_payload->''active'') is distinct from ''boolean'' or jsonb_typeof(p_payload->''is_default'') is distinct from ''boolean''\n  or ((p_payload->>''is_default'')::boolean and not (p_payload->>''active'')::boolean) then raise exception ''ADVISORY_JOURNEY_INVALID''; end if;\n  if (p_payload->>''is_default'')::boolean then\n   update public.advisory_journey_variants set is_default=false,revision=revision+1 where family_key=family and is_default and id<>v.id;\n  end if;\n  update public.advisory_journey_variants set active=(p_payload->>''active'')::boolean,is_default=(p_payload->>''is_default'')::boolean where id=v.id;\n else raise exception ''ADVISORY_ACTION_INVALID''; end if;\n if not exists(select 1 from public.advisory_journey_variants where family_key=family and active and is_default) then raise exception ''ADVISORY_JOURNEY_DEFAULT_REQUIRED''; end if;\n if p_action<>''create'' then update public.advisory_journey_variants set revision=revision+1 where id=v.id; end if;\n select to_jsonb(x) into result from public.advisory_journey_variants x where id=v.id;\n insert into public.advisory_journey_requests(request_id,actor_id,body,response,previous_state,resulting_state) values(p_request_id,actor,body,result,before_state,result||jsonb_build_object(''published_version'',ver));\n return result;\nend; $function$\n","volatility":"v","security_definer":true}}}'::jsonb) FROM original x(state),journey y(j))
 SELECT s||jsonb_build_object(
 'targets_exact',(s->>'targets_exact')::boolean AND (SELECT array_agg(matter_no ORDER BY matter_no COLLATE "C")=ARRAY['ADV-2026-004','ADV-2026-005','ADV-2026-006','ADV-2026-007','ADV-2026-008','ADV-2026-009','ADV-2026-010','ADV-2026-011','ADV-2026-012'] FROM public.advisory_matters WHERE matter_no=ANY(ARRAY['ADV-2026-004','ADV-2026-005','ADV-2026-006','ADV-2026-007','ADV-2026-008','ADV-2026-009','ADV-2026-010','ADV-2026-011','ADV-2026-012'])),
 'legacy_origin_readable',NOT EXISTS(SELECT 1 FROM public.advisory_matter_activities a JOIN public.advisory_matters m ON m.id=a.matter_id WHERE m.matter_no=ANY(ARRAY['ADV-2026-004','ADV-2026-005','ADV-2026-006','ADV-2026-007','ADV-2026-008','ADV-2026-009','ADV-2026-010','ADV-2026-011','ADV-2026-012']) AND a.kind='create'),
 'contract095_exact',f='{"guards":[["advisory_advice_records","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_advice_records FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_deliverables","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_deliverables FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_issue_tasks","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_issue_tasks FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_issues","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_issues FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_journey_snapshots","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_journey_snapshots FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_activities","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_activities FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_control","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_control FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_stages","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_stages FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matter_team","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matter_team FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_matters","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_matters FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''id'')"],["advisory_stage_visits","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_stage_visits FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"],["advisory_time_logs","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_time_logs FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''advisory_matter_id'')"],["advisory_work_state_events","advisory095_write_guard","O","CREATE TRIGGER advisory095_write_guard BEFORE INSERT OR DELETE OR UPDATE ON advisory_work_state_events FOR EACH ROW EXECUTE FUNCTION advisory095_write_guard(''matter_id'')"]],"functions":{"advisory095_capture()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_capture()\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$ WITH targets(id,matter_no) AS (VALUES (''8f375864-0fb3-4d17-9e07-d4f6d76cf4fe''::uuid,''ADV-2026-013''),(''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid,''ADV-2026-014''),(''02e5ba61-af9b-4dc0-8729-9e334639b652''::uuid,''ADV-2026-015''),(''c9aa7141-ed6a-4cdd-926a-ad261fb93dd6''::uuid,''ADV-2026-016''),(''47bfb55e-3ac5-445c-b335-5d48417f793e''::uuid,''ADV-2026-017''),(''7442060f-5a6b-4235-a826-597a6a53bb37''::uuid,''ADV-2026-018''),(''b02ba4f6-ccc8-43df-91d1-9d584ef6a7e0''::uuid,''ADV-2026-019''),(''6c717f2e-aff6-44af-9774-e910d7a61047''::uuid,''ADV-2026-020''),(''35583652-f594-4d7b-8f6a-24991df14dad''::uuid,''ADV-2026-021''),(''50221a99-f188-4f18-9017-b6f3302a5c2f''::uuid,''ADV-2026-022''),(''8cf4af68-18cd-415f-a56e-578e4ccaa2d1''::uuid,''ADV-2026-023'')),\n rels AS MATERIALIZED (SELECT c.oid,n.nspname,c.relname,c.relkind FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN (''r'',''p'') AND NOT c.relispartition\n AND (n.nspname=''public'' AND c.relname<>''advisory_matter_archives'' OR n.nspname=''auth'' AND c.relname=''users'' OR n.nspname=''storage'' AND c.relname IN (''buckets'',''objects''))),\n rows AS MATERIALIZED (SELECT r.nspname||''.''||r.relname name,x.evidence::jsonb evidence FROM rels r CROSS JOIN LATERAL XMLTABLE(''/table/row'' PASSING query_to_xml(format(\n ''SELECT jsonb_build_object(''''count'''',count(*),''''sha256'''',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE \"C\"),''''[]''''::jsonb)::text,''''UTF8'''')),''''hex''''))::text evidence FROM %I.%I t'',r.nspname,r.relname),false,false,'''') COLUMNS evidence text PATH ''evidence'') x),\n catalog AS MATERIALIZED (SELECT n.nspname||''.''||c.relname name,jsonb_build_object(''kind'',c.relkind,''owner'',pg_get_userbyid(c.relowner),''acl'',c.relacl::text,''rls'',c.relrowsecurity,''force_rls'',c.relforcerowsecurity,''options'',c.reloptions,\n ''view'',CASE WHEN c.relkind=''v'' THEN pg_get_viewdef(c.oid,true) END,\n ''columns'',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl::text,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),\n ''constraints'',(SELECT coalesce(jsonb_agg(jsonb_build_array(k.conname,pg_get_constraintdef(k.oid,true),k.convalidated) ORDER BY k.conname COLLATE \"C\"),''[]'') FROM pg_constraint k WHERE k.conrelid=c.oid AND k.contype<>''n''),\n ''indexes'',(SELECT coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY ic.relname COLLATE \"C\"),''[]'') FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),\n ''policies'',(SELECT coalesce(jsonb_agg(to_jsonb(p)-''schemaname''-''tablename'' ORDER BY p.policyname COLLATE \"C\"),''[]'') FROM pg_policies p WHERE p.schemaname=n.nspname AND p.tablename=c.relname),\n ''triggers'',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname COLLATE \"C\"),''[]'') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND t.tgname NOT LIKE ''advisory095_%'')) evidence FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace\n WHERE c.relkind IN (''r'',''p'',''v'',''m'',''S'') AND NOT c.relispartition AND (n.nspname=''public'' AND NOT (c.relname=''advisory_matter_archives'' OR c.relname IN (''advisory_operational_matters'',''advisory_operational_issues'',''advisory_operational_tasks'',''advisory_operational_time'',''advisory_operational_advice'')) OR n.nspname=''auth'' AND c.relname=''users'' OR n.nspname=''storage'' AND c.relname IN (''objects'',''buckets''))),\n funcs AS MATERIALIZED (SELECT p.oid::regprocedure::text name,jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.proacl::text) evidence FROM pg_proc p WHERE p.pronamespace=''public''::regnamespace AND p.prokind IN (''f'',''p'') AND p.proname NOT LIKE ''advisory095_%'' AND p.oid::regprocedure::text NOT IN (''advisory_control_read(uuid,jsonb)'',''advisory_control_section(uuid,text,integer,uuid)'',''advisory_overdue_work(uuid)'',''advisory_workflow_checks(uuid)'')),\n target_rows AS MATERIALIZED (SELECT t.*,to_jsonb(m) facts FROM targets t LEFT JOIN public.advisory_matters m ON m.id=t.id AND m.matter_no=t.matter_no),\n tokens AS MATERIALIZED (SELECT array_agg(DISTINCT token) ids FROM (\n SELECT id::text token FROM targets UNION SELECT matter_no FROM targets\n UNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_issues x JOIN targets t ON t.id=x.advisory_matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_issue_tasks x JOIN targets t ON t.id=x.advisory_matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_time_logs x JOIN targets t ON t.id=x.advisory_matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_advice_records x JOIN targets t ON t.id=x.advisory_matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_control x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_team x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_stages x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_stage_visits x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_journey_snapshots x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_activities x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_work_state_events x JOIN targets t ON t.id=x.matter_id\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_deliverables x JOIN targets t ON t.id=x.matter_id\n ) x WHERE token IS NOT NULL),\n ref_columns AS (SELECT n.nspname,c.relname,a.attname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped\n WHERE n.nspname=''public'' AND c.relkind IN (''r'',''p'') AND NOT c.relispartition AND (c.relname LIKE ''finance_%'' OR c.relname=''cases'' OR c.relname LIKE ''case_%'') AND c.relname<>''case_audit_logs''\n AND (a.atttypid IN (''json''::regtype,''jsonb''::regtype) OR a.attname ~ ''(advisory|matter|issue|task|source|origin|record|entity|object|target).*(id|ids|no|reference)$''\n OR EXISTS(SELECT 1 FROM pg_constraint k WHERE k.contype=''f'' AND k.conrelid=c.oid AND a.attnum=ANY(k.conkey) AND k.confrelid IN(SELECT to_regclass(''public.''||x) FROM unnest(ARRAY[''advisory_matters'',''advisory_issues'',''advisory_issue_tasks'',''advisory_time_logs'',''advisory_advice_records'',''advisory_matter_control'',''advisory_matter_team'',''advisory_matter_stages'',''advisory_stage_visits'',''advisory_journey_snapshots'',''advisory_matter_activities'',''advisory_work_state_events'',''advisory_deliverables'']) x)))),\n refs AS MATERIALIZED (SELECT r.relname table_name,x.n FROM (SELECT nspname,relname,string_agg(format(''EXISTS(SELECT 1 FROM unnest(%L::text[]) tok WHERE strpos(coalesce(r.%I::text,''''''''),tok)>0)'',tokens.ids::text,attname),'' OR '' ORDER BY attname) predicate FROM ref_columns CROSS JOIN tokens GROUP BY nspname,relname) r\n CROSS JOIN LATERAL XMLTABLE(''/table/row'' PASSING query_to_xml(format(''SELECT count(*)::bigint n FROM %I.%I r WHERE %s'',r.nspname,r.relname,r.predicate),false,false,'''') COLUMNS n bigint PATH ''n'') x WHERE x.n>0),\n raw AS (SELECT (SELECT jsonb_object_agg(name,evidence) FROM rows) rows,\n jsonb_build_object(''relations'',(SELECT jsonb_object_agg(name,evidence) FROM catalog),''functions'',(SELECT jsonb_object_agg(name,evidence) FROM funcs),\n ''roles'',(SELECT jsonb_agg(jsonb_build_array(rolname,rolsuper,rolinherit,rolbypassrls) ORDER BY rolname COLLATE \"C\") FROM pg_roles),\n ''members'',(SELECT jsonb_agg(jsonb_build_array(roleid::regrole::text,member::regrole::text,admin_option) ORDER BY roleid::regrole::text COLLATE \"C\",member::regrole::text COLLATE \"C\") FROM pg_auth_members)) preserved,\n (SELECT jsonb_agg(jsonb_build_object(''id'',id,''matter_no'',matter_no,''sha256'',encode(sha256(convert_to((facts)::text,''UTF8'')),''hex'')) ORDER BY matter_no COLLATE \"C\") FROM target_rows) targets,\n (SELECT count(*)=11 AND bool_and(facts IS NOT NULL) FROM target_rows) AND (SELECT count(*)=11 FROM public.advisory_matters WHERE matter_no IN(SELECT matter_no FROM targets)) targets_exact)\n SELECT jsonb_build_object(''rows_sha256'',encode(sha256(convert_to((rows)::text,''UTF8'')),''hex''),''preserved_sha256'',encode(sha256(convert_to((preserved)::text,''UTF8'')),''hex''),''targets_sha256'',encode(sha256(convert_to((targets)::text,''UTF8'')),''hex''),\n ''row_fingerprints'',rows,''targets'',targets,''targets_exact'',targets_exact,\n ''protected_count'',(SELECT count(*) FROM public.advisory_matters WHERE matter_no=ANY(ARRAY[''ADV-2026-004'',''ADV-2026-005'',''ADV-2026-006'',''ADV-2026-007'',''ADV-2026-008'',''ADV-2026-009'',''ADV-2026-010'',''ADV-2026-011'',''ADV-2026-012''])),\n ''external_references'',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY table_name COLLATE \"C\"),''[]'') FROM refs r),\n ''reviewed_special_evidence'',jsonb_build_object(''time_023_minutes'',(SELECT coalesce(sum(minutes),0) FROM public.advisory_time_logs WHERE advisory_matter_id=''8cf4af68-18cd-415f-a56e-578e4ccaa2d1''::uuid),\n ''snapshot_matters'',(SELECT coalesce(jsonb_agg(m.matter_no ORDER BY m.matter_no COLLATE \"C\"),''[]'') FROM public.advisory_journey_snapshots s JOIN public.advisory_matters m ON m.id=s.matter_id WHERE m.matter_no=ANY(ARRAY[''ADV-2026-019'',''ADV-2026-020'',''ADV-2026-021'',''ADV-2026-022'',''ADV-2026-023''])),\n ''audit_014_count'',(SELECT count(*) FROM public.case_audit_logs a WHERE a.table_name LIKE ''advisory_%'' AND a.record_id IN(\n SELECT ''7583d780-9e98-4852-bf5a-98c40fbf8072'' UNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_issues x WHERE x.advisory_matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_issue_tasks x WHERE x.advisory_matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_time_logs x WHERE x.advisory_matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_advice_records x WHERE x.advisory_matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_control x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_team x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_stages x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_stage_visits x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_journey_snapshots x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_matter_activities x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_work_state_events x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid\nUNION SELECT to_jsonb(x)->>''id'' FROM public.advisory_deliverables x WHERE x.matter_id=''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid)))) FROM raw; $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory095_targets()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_targets()\n RETURNS TABLE(id uuid, matter_no text)\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$ VALUES (''8f375864-0fb3-4d17-9e07-d4f6d76cf4fe''::uuid,''ADV-2026-013''),(''7583d780-9e98-4852-bf5a-98c40fbf8072''::uuid,''ADV-2026-014''),(''02e5ba61-af9b-4dc0-8729-9e334639b652''::uuid,''ADV-2026-015''),(''c9aa7141-ed6a-4cdd-926a-ad261fb93dd6''::uuid,''ADV-2026-016''),(''47bfb55e-3ac5-445c-b335-5d48417f793e''::uuid,''ADV-2026-017''),(''7442060f-5a6b-4235-a826-597a6a53bb37''::uuid,''ADV-2026-018''),(''b02ba4f6-ccc8-43df-91d1-9d584ef6a7e0''::uuid,''ADV-2026-019''),(''6c717f2e-aff6-44af-9774-e910d7a61047''::uuid,''ADV-2026-020''),(''35583652-f594-4d7b-8f6a-24991df14dad''::uuid,''ADV-2026-021''),(''50221a99-f188-4f18-9017-b6f3302a5c2f''::uuid,''ADV-2026-022''),(''8cf4af68-18cd-415f-a56e-578e4ccaa2d1''::uuid,''ADV-2026-023''); $function$\n","volatility":"i","service_role":false,"authenticated":false},"advisory095_write_guard()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_write_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE ids uuid[]; k uuid;\nBEGIN\n ids:=ARRAY[CASE WHEN TG_OP<>''DELETE'' THEN (to_jsonb(NEW)->>TG_ARGV[0])::uuid END,\n            CASE WHEN TG_OP<>''INSERT'' THEN (to_jsonb(OLD)->>TG_ARGV[0])::uuid END];\n FOR k IN SELECT DISTINCT x FROM unnest(ids) x WHERE x IS NOT NULL ORDER BY x LOOP\n  PERFORM 1 FROM public.advisory_matters WHERE id=k FOR UPDATE;\n  IF EXISTS(SELECT 1 FROM public.advisory_matter_archives WHERE matter_id=k) THEN\n   RAISE EXCEPTION ''ADVISORY_ARCHIVED'' USING ERRCODE=''55000'';\n  END IF;\n END LOOP;\n IF TG_OP=''DELETE'' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory_overdue_work(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_overdue_work(p_matter_id uuid DEFAULT NULL::uuid)\n RETURNS TABLE(matter_id uuid, source text, source_id uuid, title text, assignee_user_id uuid, assignee_name text, due_date date, overdue_days integer, is_next_action boolean)\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare today date:=(current_timestamp at time zone ''Asia/Bangkok'')::date;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n -- Invoker/RLS remains authoritative. Identity is (source, source_id), never title.\n return query\n with open_matters as materialized (\n  select m.id,c.next_task_id,c.next_action,c.next_owner_id,c.next_due\n  from public.advisory_operational_matters m left join public.advisory_matter_control c on c.matter_id=m.id\n  where (p_matter_id is null or m.id=p_matter_id)\n   and m.status not in (''completed'',''cancelled'') and c.closed_at is null\n )\n select m.id,''task''::text,t.id,t.title,t.assignee_user_id,\n  coalesce(nullif(p.staff_name,''''),p.full_name,t.assignee_name),t.due_date,today-t.due_date,\n  coalesce(m.next_task_id=t.id,false)\n from open_matters m join public.advisory_issue_tasks t on t.advisory_matter_id=m.id\n left join public.user_profiles p on p.id=t.assignee_user_id\n where t.deleted_at is null and t.completed_at is null\n  and t.status in (''pending'',''in_progress'',''waiting'') and t.due_date<today\n union all\n select m.id,''next_action''::text,m.id,m.next_action,m.next_owner_id,\n  coalesce(nullif(p.staff_name,''''),p.full_name),m.next_due,today-m.next_due,true\n from open_matters m left join public.user_profiles p on p.id=m.next_owner_id\n where m.next_task_id is null and nullif(btrim(m.next_action),'''') is not null and m.next_due<today;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory095_operational(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_operational(p_matter_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\n SELECT public.advisory076_allowed(''read'') AND NOT EXISTS(\n  SELECT 1 FROM public.advisory_matter_archives a WHERE a.matter_id=p_matter_id);\n$function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory_workflow_checks(uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_workflow_checks(p_matter_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare m public.advisory_matters%rowtype; c public.advisory_matter_control%rowtype;\n visit public.advisory_stage_visits%rowtype; stage public.advisory_matter_stages%rowtype;\n open_tasks bigint; pending_deliverables bigint; uncompleted_stages bigint; stage_open_tasks bigint;\n has_next boolean; result jsonb; fj jsonb; options jsonb;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n select * into m from public.advisory_operational_matters where id=p_matter_id;\n if not found then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n select * into c from public.advisory_matter_control where matter_id=m.id;\n select * into visit from public.advisory_stage_visits where matter_id=m.id and kind=''visit'' and exited_at is null;\n select * into stage from public.advisory_matter_stages where id=visit.stage_id;\n select count(*) into open_tasks from public.advisory_issue_tasks where advisory_matter_id=m.id and deleted_at is null and status not in (''completed'',''cancelled'');\n select count(*) into stage_open_tasks from public.advisory_issue_tasks where advisory_matter_id=m.id and stage_id=stage.id and deleted_at is null and status not in (''completed'',''cancelled'');\n select count(*) into pending_deliverables from public.advisory_deliverables where matter_id=m.id and status not in (''delivered'',''cancelled'');\n select count(*) into uncompleted_stages from public.advisory_matter_stages s where s.matter_id=m.id and s.stage_key<>''close''\n and not exists(select 1 from public.advisory_stage_visits v where v.stage_id=s.id and\n  (v.kind=''skip'' or (v.kind=''visit'' and v.exited_at is not null)));\n select definition into fj from public.advisory_journey_snapshots where matter_id=m.id;\n if fj->''format''=''2''::jsonb then\n  select s->''outcomes'' into options from jsonb_array_elements(fj->''stages'') s where s->>''key''=stage.stage_key;\n  -- Only the actual chosen route affects closing; unchosen branches are not\n  -- incomplete work, and no skip/history is fabricated for them.\n  uncompleted_stages:=case when visit.id is null and exists(\n   select 1 from public.advisory_matter_activities a where a.matter_id=m.id and a.kind in (''stage_complete'',''stage_skip'')\n    and a.detail->>''journey_format''=''2'' and a.detail->>''next_stage_key''=''close''\n    and a.detail->>''from_visit_id''=(select v.id::text from public.advisory_stage_visits v where v.matter_id=m.id and v.kind=''visit'' order by v.entered_at desc,v.recorded_at desc,v.id desc limit 1)\n  ) then 0 else 1 end;\n end if;\n has_next:=c.next_task_id is not null or c.next_action is not null;\n result:=jsonb_build_object(''matter_id'',m.id,''version'',coalesce(c.version,0),''lifecycle'',m.status,\n  ''closed'',c.closed_at is not null or m.status in (''completed'',''cancelled''),\n  ''current_visit_id'',visit.id,''current_stage_id'',stage.id,''current_stage_key'',stage.stage_key,\n  ''current_stage_open_tasks'',stage_open_tasks,''open_tasks'',open_tasks,''has_next_action'',has_next,\n  ''pending_deliverables'',pending_deliverables,''uncompleted_stages'',uncompleted_stages,\n  ''stage_ready'',visit.id is null and uncompleted_stages=0,\n  ''legacy_without_plan'',not exists(select 1 from public.advisory_matter_stages where matter_id=m.id),\n  ''ready_to_close'',open_tasks=0 and not has_next and pending_deliverables=0 and visit.id is null and uncompleted_stages=0);\n if fj->''format''=''2''::jsonb then result:=result||jsonb_build_object(''journey_format'',2,''outcomes'',coalesce(options,''[]''::jsonb),\n  ''route_stages'',(select jsonb_agg(s-''outcomes'' order by n) from jsonb_array_elements(fj->''stages'') with ordinality x(s,n))); end if;\n return result;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory095_archive_immutable()":{"acl":"{postgres=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_archive_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nBEGIN RAISE EXCEPTION ''ADVISORY_ARCHIVE_IMMUTABLE''; END $function$\n","volatility":"v","service_role":false,"authenticated":false},"advisory_control_read(uuid,jsonb)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_control_read(p_matter_id uuid DEFAULT NULL::uuid, p_query jsonb DEFAULT ''{}''::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare result jsonb; today date:=(current_timestamp at time zone ''Asia/Bangkok'')::date;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n with overdue_items as materialized (select * from public.advisory_overdue_work()),\n ranked_overdue as (\n  select o.*,row_number() over(partition by matter_id order by due_date,source COLLATE \"C\",source_id) position from overdue_items o\n ), overdue as (\n  select matter_id,count(*) overdue_item_count,min(due_date) oldest_overdue_due,max(overdue_days) oldest_overdue_days,\n   coalesce(max(overdue_days) filter(where is_next_action),0) next_action_overdue_days,\n   jsonb_agg(to_jsonb(o)-''matter_id''-''position'' order by due_date,source COLLATE \"C\",source_id) filter(where position<=3) overdue_preview\n  from ranked_overdue o group by matter_id\n ), items as (\n select m.*,coalesce(o.overdue_item_count,0)>0 has_overdue_work,\n coalesce(o.overdue_item_count,0) overdue_item_count,o.oldest_overdue_due,coalesce(o.oldest_overdue_days,0) oldest_overdue_days,\n coalesce(o.next_action_overdue_days,0) next_action_overdue_days,coalesce(o.overdue_preview,''[]''::jsonb) overdue_preview,\n cl.name client_name,coalesce(c.version,0) version,c.work_state,c.closed_at,c.outcome,c.outcome_summary,c.follow_up,c.case_reference,\n c.next_task_id,coalesce(t.title,c.next_action) next_action,coalesce(t.assignee_user_id,c.next_owner_id) next_owner_id,\n coalesce(nullif(np.staff_name,''''),np.full_name,t.assignee_name) next_owner_name,coalesce(t.due_date,c.next_due) next_due,\n lead.user_id lead_id,coalesce(nullif(lp.staff_name,''''),lp.full_name,m.responsible_lawyer) lead_name,\n st.stage_key,st.template_key,v.entered_at,\n (select s->>''name_th'' from public.advisory_journey_snapshots j,lateral jsonb_array_elements(j.definition->''stages'') s where j.matter_id=m.id and s->>''key''=st.stage_key) stage_name_th,\n (select s->>''name_en'' from public.advisory_journey_snapshots j,lateral jsonb_array_elements(j.definition->''stages'') s where j.matter_id=m.id and s->>''key''=st.stage_key) stage_name_en,\n case when v.entered_at is not null then greatest(0,today-(v.entered_at at time zone ''Asia/Bangkok'')::date) end stage_days,\n greatest(0,coalesce((c.closed_at at time zone ''Asia/Bangkok'')::date,today)-coalesce(m.start_date,(m.created_at at time zone ''Asia/Bangkok'')::date)) age_days\n from public.advisory_operational_matters m join public.clients cl on cl.id=m.client_id\n left join overdue o on o.matter_id=m.id\n left join public.advisory_matter_control c on c.matter_id=m.id\n left join public.advisory_issue_tasks t on t.id=c.next_task_id and t.deleted_at is null and t.status in (''pending'',''in_progress'',''waiting'') and t.completed_at is null\n left join public.user_profiles np on np.id=coalesce(t.assignee_user_id,c.next_owner_id)\n left join public.advisory_matter_team lead on lead.matter_id=m.id and lead.team_role=''lead''\n left join public.user_profiles lp on lp.id=lead.user_id\n left join public.advisory_stage_visits v on v.matter_id=m.id and v.kind=''visit'' and v.exited_at is null\n left join public.advisory_matter_stages st on st.id=v.stage_id\n ), filtered as (\n select * from items i where (p_matter_id is null or i.id=p_matter_id)\n and (coalesce(p_query->>''search'','''')='''' or concat_ws('' '',i.matter_no,i.title,i.client_name,i.lead_name) ilike ''%''||(p_query->>''search'')||''%'')\n and (coalesce(p_query->>''client_id'','''')='''' or i.client_id::text=p_query->>''client_id'')\n and (coalesce(p_query->>''type'','''')='''' or i.matter_type=p_query->>''type'')\n and (coalesce(p_query->>''lead'','''')='''' or i.lead_id::text=p_query->>''lead'')\n and (coalesce(p_query->>''state'','''')='''' or i.work_state=p_query->>''state'')\n and case coalesce(p_query->>''tab'',''all'') when ''mine'' then exists(select 1 from public.advisory_matter_team tm where tm.matter_id=i.id and tm.user_id=auth.uid()) or i.next_owner_id=auth.uid()\n when ''overdue'' then i.has_overdue_work\n when ''missing'' then i.closed_at is null and i.next_action is null\n when ''closed'' then i.closed_at is not null else true end\n ), page as (\n select * from filtered order by case when p_query->>''sort''=''due'' then next_due end asc nulls last,created_at desc,id\n limit least(50,greatest(1,coalesce((p_query->>''limit'')::int,20))) offset greatest(0,coalesce((p_query->>''offset'')::int,0))\n ) select jsonb_build_object(''items'',coalesce((select jsonb_agg(to_jsonb(p)) from page p),''[]''),''total'',(select count(*) from filtered),\n ''summary'',(select jsonb_build_object(''open'',count(*) filter(where closed_at is null and status not in (''completed'',''cancelled'')),\n ''overdue'',count(*) filter(where has_overdue_work),''overdue_items'',coalesce(sum(overdue_item_count),0),''waiting'',count(*) filter(where closed_at is null and work_state=''waiting_client''),\n ''closed_week'',count(*) filter(where closed_at>=date_trunc(''week'',current_timestamp at time zone ''Asia/Bangkok'') at time zone ''Asia/Bangkok'')) from items),\n ''permissions'',jsonb_build_object(''manage'',public.advisory076_allowed(''manage''),''task'',public.advisory076_allowed(''task''),''delete'',public.advisory076_allowed(''delete''))) into result;\n if p_matter_id is not null then\n  if jsonb_array_length(result->''items'')<>1 then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n  result:=result||jsonb_build_object(\n   ''journey_path'',(select coalesce(jsonb_agg(to_jsonb(v) order by v.entered_at,v.recorded_at,v.id),''[]''::jsonb) from public.advisory_stage_visits v where v.matter_id=p_matter_id and v.kind=''visit''),\n   ''journey_decisions'',(select coalesce(jsonb_agg(jsonb_build_object(''id'',a.id,''actor_id'',a.actor_id,''occurred_at'',a.occurred_at,''kind'',a.kind,''detail'',a.detail) order by a.occurred_at,a.id),''[]''::jsonb) from public.advisory_matter_activities a where a.matter_id=p_matter_id and a.detail->>''journey_format''=''2''),\n   ''journey_snapshot'',(select to_jsonb(j) from public.advisory_journey_snapshots j where matter_id=p_matter_id),\n   ''state_history'',(select coalesce(jsonb_agg(to_jsonb(x) order by x.started_at desc),''[]'') from (select work_state,started_at,ended_at,reason from public.advisory_work_state_events where matter_id=p_matter_id order by started_at desc limit 10) x),\n   ''team'',(select coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object(''name'',coalesce(nullif(p.staff_name,''''),p.full_name)) order by t.team_role,p.full_name),''[]'') from public.advisory_matter_team t join public.user_profiles p on p.id=t.user_id where t.matter_id=p_matter_id),\n   ''stages'',(select coalesce(jsonb_agg(to_jsonb(s)||coalesce((select element-''key'' from public.advisory_journey_snapshots j, lateral jsonb_array_elements(j.definition->''stages'') element where j.matter_id=s.matter_id and element->>''key''=s.stage_key),''{}''::jsonb)||jsonb_build_object(''visits'',coalesce(v.rows,''[]''),''minutes'',tm.minutes,''elapsed_seconds'',(select sum(extract(epoch from coalesce(exited_at,current_timestamp)-entered_at)) from public.advisory_stage_visits where stage_id=s.id and kind=''visit''),''task_total'',(select count(*) from public.advisory_issue_tasks where stage_id=s.id and deleted_at is null),''task_completed'',(select count(*) from public.advisory_issue_tasks where stage_id=s.id and deleted_at is null and status=''completed''),''unclassified'',tm.unclassified) order by s.position),''[]'')\n    from public.advisory_matter_stages s\n    left join lateral(select jsonb_agg(to_jsonb(x) order by recorded_at desc) rows from (select * from public.advisory_stage_visits where stage_id=s.id order by recorded_at desc limit 20) x) v on true\n    left join lateral(select sum(minutes) minutes,count(*) filter(where stage_id is null) unclassified from public.advisory_time_logs where advisory_matter_id=p_matter_id and stage_id=s.id and deleted_at is null) tm on true where s.matter_id=p_matter_id),\n   ''time'',(select jsonb_build_object(''minutes'',coalesce(sum(minutes),0),''core'',coalesce(sum(minutes) filter(where billable),0),''support'',coalesce(sum(minutes) filter(where not billable),0),''unclassified'',count(*) filter(where stage_id is null)) from public.advisory_time_logs where advisory_matter_id=p_matter_id and deleted_at is null),\n   ''other_matters'',(select coalesce(jsonb_agg(to_jsonb(x)),''[]'') from (select id,matter_no,title,status from public.advisory_operational_matters where client_id=(select client_id from public.advisory_operational_matters where id=p_matter_id) and id<>p_matter_id order by created_at desc limit 5) x));\n end if;\n return result;\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true},"advisory095_archive_uat(uuid,text,jsonb)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"definition":"CREATE OR REPLACE FUNCTION public.advisory095_archive_uat(p_request_id uuid, p_reason text, p_reviewed jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''pg_catalog'', ''public''\nAS $function$\nDECLARE actor uuid:=auth.uid(); state jsonb; after_state jsonb; r record; n integer;\n moment timestamptz:=clock_timestamp();\nBEGIN\n IF NOT coalesce(public.advisory086_admin(),false) THEN\n  RAISE EXCEPTION ''ADVISORY_FORBIDDEN'' USING ERRCODE=''42501'';\n END IF;\n IF p_request_id IS NULL OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000\n  OR p_reviewed IS NULL OR jsonb_typeof(p_reviewed)<>''object''\n  OR coalesce(p_reviewed->>''rows_sha256'','''') !~ ''^[0-9a-f]{64}$''\n  OR coalesce(p_reviewed->>''preserved_sha256'','''') !~ ''^[0-9a-f]{64}$''\n  OR coalesce(p_reviewed->>''targets_sha256'','''') !~ ''^[0-9a-f]{64}$''\n THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_REVIEW_REQUIRED''; END IF;\n PERFORM pg_advisory_xact_lock(hashtextextended(''advisory095-fixed-uat-batch'',0));\n -- One-time maintenance operation: short, deterministic SHARE locks keep the\n -- whole reviewed preservation snapshot stable. No business table is written.\n FOR r IN SELECT n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace\n  WHERE c.relkind IN (''r'',''p'') AND NOT c.relispartition AND\n   (n.nspname=''public'' OR n.nspname=''auth'' AND c.relname=''users''\n    OR n.nspname=''storage'' AND c.relname IN (''buckets'',''objects''))\n  AND c.relname<>''advisory_matter_archives'' ORDER BY n.nspname COLLATE \"C\",c.relname COLLATE \"C\"\n LOOP EXECUTE format(''LOCK TABLE %I.%I IN SHARE MODE'',r.nspname,r.relname); END LOOP;\n LOCK TABLE public.advisory_matter_archives IN EXCLUSIVE MODE;\n IF NOT coalesce(public.advisory086_admin(),false) THEN\n  RAISE EXCEPTION ''ADVISORY_FORBIDDEN'' USING ERRCODE=''42501'';\n END IF;\n PERFORM m.id FROM public.advisory_matters m JOIN public.advisory095_targets() t ON t.id=m.id ORDER BY m.id FOR UPDATE OF m;\n SELECT public.advisory095_capture() INTO state;\n IF NOT coalesce((state->>''targets_exact'')::boolean,false) THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_IDENTITY_CHANGED''; END IF;\n IF (state->>''protected_count'')::integer<>9\n  OR (state#>>''{reviewed_special_evidence,time_023_minutes}'')::bigint<>90\n  OR (state#>>''{reviewed_special_evidence,audit_014_count}'')::bigint<1\n  OR state#>''{reviewed_special_evidence,snapshot_matters}''<>''[\"ADV-2026-019\",\"ADV-2026-020\",\"ADV-2026-021\",\"ADV-2026-022\",\"ADV-2026-023\"]''::jsonb\n THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_REVIEWED_EVIDENCE_CHANGED''; END IF;\n IF state->>''rows_sha256'' IS DISTINCT FROM p_reviewed->>''rows_sha256''\n  OR state->>''preserved_sha256'' IS DISTINCT FROM p_reviewed->>''preserved_sha256''\n  OR state->>''targets_sha256'' IS DISTINCT FROM p_reviewed->>''targets_sha256''\n THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_REVIEW_STALE''; END IF;\n IF state->''external_references''<>''[]''::jsonb THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_EXTERNAL_REFERENCE''; END IF;\n SELECT count(*) INTO n FROM public.advisory_matter_archives;\n IF n<>0 THEN\n  IF n=11 AND NOT EXISTS(SELECT 1 FROM public.advisory_matter_archives a\n    LEFT JOIN public.advisory095_targets() t ON t.id=a.matter_id AND t.matter_no=a.matter_no\n    WHERE t.id IS NULL OR a.request_id<>p_request_id OR a.archived_by<>actor\n     OR a.archive_reason<>btrim(p_reason) OR a.reviewed_baseline<>p_reviewed\n     OR a.reviewed_matter_sha256<>(SELECT encode(sha256(convert_to(to_jsonb(m)::text,''UTF8'')),''hex'')\n       FROM public.advisory_matters m WHERE m.id=a.matter_id))\n  THEN RETURN jsonb_build_object(''archived'',11,''request_id'',p_request_id,''replayed'',true); END IF;\n  RAISE EXCEPTION ''ADVISORY_ARCHIVE_RETRY_MISMATCH'';\n END IF;\n INSERT INTO public.advisory_matter_archives(matter_id,matter_no,archived_at,archived_by,archive_reason,request_id,reviewed_matter_sha256,reviewed_baseline)\n SELECT m.id,m.matter_no,moment,actor,btrim(p_reason),p_request_id,\n  encode(sha256(convert_to(to_jsonb(m)::text,''UTF8'')),''hex''),p_reviewed\n FROM public.advisory_matters m JOIN public.advisory095_targets() t ON t.id=m.id AND t.matter_no=m.matter_no;\n GET DIAGNOSTICS n=ROW_COUNT;\n IF n<>11 THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_TARGET_COUNT''; END IF;\n SELECT public.advisory095_capture() INTO after_state;\n IF state IS DISTINCT FROM after_state THEN RAISE EXCEPTION ''ADVISORY_ARCHIVE_PRESERVATION_FAILED''; END IF;\n RETURN jsonb_build_object(''archived'',n,''request_id'',p_request_id,''replayed'',false);\nEND $function$\n","volatility":"v","service_role":false,"authenticated":true},"advisory_control_section(uuid,text,integer,uuid)":{"acl":"{postgres=X/postgres,authenticated=X/postgres}","anon":false,"owner":"postgres","config":["search_path=public"],"definer":false,"definition":"CREATE OR REPLACE FUNCTION public.advisory_control_section(p_matter_id uuid, p_section text, p_offset integer DEFAULT 0, p_issue_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''public''\nAS $function$\ndeclare tab text; predicate text; ordering text; rows jsonb; total bigint;\nbegin\n if not public.advisory076_allowed(''read'') then raise exception ''ADVISORY_FORBIDDEN'' using errcode=''42501''; end if;\n if not exists(select 1 from public.advisory_operational_matters where id=p_matter_id) then raise exception ''ADVISORY_MATTER_NOT_FOUND''; end if;\n case p_section\n when ''tasks'' then tab:=''advisory_issue_tasks''; predicate:=''advisory_matter_id=$1 and deleted_at is null and ($3 is null or advisory_issue_id=$3)''; ordering:=''case when status in (''''completed'''',''''cancelled'''') then 1 else 0 end,due_date nulls last,id'';\n when ''deleted_tasks'' then tab:=''advisory_issue_tasks''; predicate:=''advisory_matter_id=$1 and deleted_at is not null and ($3 is null or advisory_issue_id=$3)''; ordering:=''deleted_at desc,id'';\n when ''activity'' then tab:=''advisory_matter_activities''; predicate:=''matter_id=$1''; ordering:=''occurred_at desc,id'';\n when ''deliverables'' then tab:=''advisory_deliverables''; predicate:=''matter_id=$1''; ordering:=''due_date nulls last,id'';\n when ''visits'' then tab:=''advisory_stage_visits''; predicate:=''matter_id=$1''; ordering:=''recorded_at desc,id'';\n when ''states'' then tab:=''advisory_work_state_events''; predicate:=''matter_id=$1''; ordering:=''started_at desc,id'';\n else raise exception ''ADVISORY_SECTION_INVALID''; end case;\n execute format(''select count(*) from public.%I where %s'',tab,predicate) into total using p_matter_id,p_offset,p_issue_id;\n execute format(''select coalesce(jsonb_agg(to_jsonb(t)),''''[]'''') from (select * from public.%I where %s order by %s limit 20 offset $2) t'',tab,predicate,ordering)\n into rows using p_matter_id,greatest(0,p_offset),p_issue_id;\n if p_section=''tasks'' then\n  -- Enrich the existing bounded Task page from the same canonical source once.\n  with overdue as materialized (select * from public.advisory_overdue_work(p_matter_id))\n  select coalesce(jsonb_agg(t.value||jsonb_build_object(''overdue_days'',coalesce(o.overdue_days,0)) order by t.position),''[]''::jsonb)\n  into rows from jsonb_array_elements(rows) with ordinality t(value,position)\n  left join overdue o on o.source=''task'' and o.source_id=(t.value->>''id'')::uuid;\n end if;\n return jsonb_build_object(''items'',rows,''total'',total);\nend; $function$\n","volatility":"s","service_role":false,"authenticated":true}},"relations":{"advisory_matter_archives":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":true,"kind":"r","view":null,"owner":"postgres","columns":[["matter_id","uuid",true,"","",null,null],["matter_no","text",true,"","",null,null],["archived_at","timestamp with time zone",true,"","",null,null],["archived_by","uuid",true,"","",null,null],["archive_reason","text",true,"","",null,null],["request_id","uuid",true,"","",null,null],["reviewed_matter_sha256","text",true,"","",null,null],["reviewed_baseline","jsonb",true,"","",null,null]],"indexes":["CREATE UNIQUE INDEX advisory_matter_archives_matter_no_key ON public.advisory_matter_archives USING btree (matter_no)","CREATE UNIQUE INDEX advisory_matter_archives_pkey ON public.advisory_matter_archives USING btree (matter_id)"],"options":null,"policies":[{"cmd":"SELECT","qual":"advisory086_admin()","roles":["authenticated"],"permissive":"PERMISSIVE","policyname":"advisory095_admin_evidence","with_check":null}],"triggers":[["advisory095_archive_immutable","O","CREATE TRIGGER advisory095_archive_immutable BEFORE DELETE OR UPDATE ON advisory_matter_archives FOR EACH ROW EXECUTE FUNCTION advisory095_archive_immutable()"]],"force_rls":false,"constraints":[["advisory_matter_archives_archive_reason_check","CHECK (length(btrim(archive_reason)) >= 1 AND length(btrim(archive_reason)) <= 2000)",true],["advisory_matter_archives_archived_by_fkey","FOREIGN KEY (archived_by) REFERENCES user_profiles(id) ON DELETE RESTRICT",true],["advisory_matter_archives_matter_id_fkey","FOREIGN KEY (matter_id) REFERENCES advisory_matters(id) ON DELETE RESTRICT",true],["advisory_matter_archives_matter_no_key","UNIQUE (matter_no)",true],["advisory_matter_archives_pkey","PRIMARY KEY (matter_id)",true],["advisory_matter_archives_reviewed_baseline_check","CHECK (jsonb_typeof(reviewed_baseline) = ''object''::text)",true],["advisory_matter_archives_reviewed_matter_sha256_check","CHECK (reviewed_matter_sha256 ~ ''^[0-9a-f]{64}$''::text)",true]]},"advisory_operational_time":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":false,"kind":"v","view":" SELECT id,\n    advisory_matter_id,\n    client_id,\n    work_date,\n    staff_name,\n    work_type,\n    work_other,\n    minutes,\n    billable,\n    note,\n    created_at,\n    updated_at,\n    deleted_at,\n    deleted_by,\n    advisory_issue_id,\n    created_by_user_id,\n    created_by_email,\n    created_by_name,\n    stage_id\n   FROM advisory_time_logs b\n  WHER