ull],["deleted_by","text",false,"","",null,null]],"indexes":[],"options":["security_invoker=true","security_barrier=true"],"policies":[],"triggers":[],"force_rls":false,"constraints":[]},"advisory_operational_issues":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":false,"kind":"v","view":" SELECT id,\n    advisory_matter_id,\n    client_id,\n    issue_no,\n    title,\n    issue_type,\n    status,\n    priority,\n    responsible_person,\n    opened_at,\n    due_date,\n    closed_at,\n    summary,\n    legal_position,\n    next_action,\n    note,\n    created_at,\n    updated_at,\n    deleted_at,\n    deleted_by\n   FROM advisory_issues b\n  WHERE advisory095_operational(advisory_matter_id);","owner":"postgres","columns":[["id","uuid",false,"","",null,null],["advisory_matter_id","uuid",false,"","",null,null],["client_id","uuid",false,"","",null,null],["issue_no","text",false,"","",null,null],["title","text",false,"","",null,null],["issue_type","text",false,"","",null,null],["status","text",false,"","",null,null],["priority","text",false,"","",null,null],["responsible_person","text",false,"","",null,null],["opened_at","date",false,"","",null,null],["due_date","date",false,"","",null,null],["closed_at","date",false,"","",null,null],["summary","text",false,"","",null,null],["legal_position","text",false,"","",null,null],["next_action","text",false,"","",null,null],["note","text",false,"","",null,null],["created_at","timestamp with time zone",false,"","",null,null],["updated_at","timestamp with time zone",false,"","",null,null],["deleted_at","timestamp with time zone",false,"","",null,null],["deleted_by","text",false,"","",null,null]],"indexes":[],"options":["security_invoker=true","security_barrier=true"],"policies":[],"triggers":[],"force_rls":false,"constraints":[]},"advisory_operational_matters":{"acl":"{postgres=arwdDxtm/postgres,authenticated=r/postgres}","rls":false,"kind":"v","view":" SELECT id,\n    client_id,\n    matter_no,\n    title,\n    matter_type,\n    retainer_type,\n    status,\n    responsible_lawyer,\n    start_date,\n    end_date,\n    monthly_retainer_amount,\n    scope_of_work,\n    note,\n    created_at,\n    updated_at\n   FROM advisory_matters b\n  WHERE advisory095_operational(id);","owner":"postgres","columns":[["id","uuid",false,"","",null,null],["client_id","uuid",false,"","",null,null],["matter_no","text",false,"","",null,null],["title","text",false,"","",null,null],["matter_type","text",false,"","",null,null],["retainer_type","text",false,"","",null,null],["status","text",false,"","",null,null],["responsible_lawyer","text",false,"","",null,null],["start_date","date",false,"","",null,null],["end_date","date",false,"","",null,null],["monthly_retainer_amount","numeric",false,"","",null,null],["scope_of_work","text",false,"","",null,null],["note","text",false,"","",null,null],["created_at","timestamp with time zone",false,"","",null,null],["updated_at","timestamp with time zone",false,"","",null,null]],"indexes":[],"options":["security_invoker=true","security_barrier=true"],"policies":[],"triggers":[],"force_rls":false,"constraints":[]}}}'::jsonb,
 'foundation_exact',NOT EXISTS(SELECT 1 FROM jsonb_each(foundation) x WHERE x.value IS DISTINCT FROM 'true'::jsonb),
 'prior_archives_sha256',encode(sha256(convert_to(((SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.matter_id),'[]') FROM public.advisory_matter_archives a JOIN prior p ON p.id=a.matter_id))::text,'UTF8')),'hex'),
 'prior_archive_exact',(SELECT count(*)=11 AND coalesce(bool_and(a.matter_no=p.matter_no AND a.reviewed_baseline='{"rows_sha256":"04cd32fcd217d157749c8f3c55d2d894ef8fbf9bb2b8e170b5ebc42e4d3ee5e0","preserved_sha256":"ba63a35d58eb837e1243ac96197f57181b7f15a7020315408635403ab3865620","targets_sha256":"8d4911ceb1d2636fb2c5bbb91022edfe6b0cadd31664cdcbdb32b59ff66ae703"}'::jsonb AND a.archived_by='52b8fea2-2558-4b76-a92b-2d332c0fee8e'::uuid AND a.request_id='1d10cab4-4db0-45ee-8144-07b1fd0b5765'::uuid AND a.reviewed_matter_sha256=encode(sha256(convert_to((to_jsonb(m))::text,'UTF8')),'hex')),false) FROM prior p JOIN public.advisory_matter_archives a ON a.matter_id=p.id JOIN public.advisory_matters m ON m.id=p.id)
 ) FROM original x(s),installed y(f),foundation z(foundation); $capture$;
-- Only the nine real Legacy Matters 004..012. No generic archive input or UI.
CREATE FUNCTION public.advisory096_archive_legacy(p_request_id uuid,p_reason text,p_reviewed jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE actor uuid:=auth.uid(); state jsonb; after_state jsonb; r record; n integer;
 moment timestamptz:=clock_timestamp(); expected_numbers text[]:=ARRAY['ADV-2026-004','ADV-2026-005','ADV-2026-006','ADV-2026-007','ADV-2026-008','ADV-2026-009','ADV-2026-010','ADV-2026-011','ADV-2026-012'];
BEGIN
 IF NOT coalesce(public.advisory086_admin(),false) THEN RAISE EXCEPTION 'ADVISORY_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000
  OR p_reviewed IS NULL OR jsonb_typeof(p_reviewed)<>'object'
  OR jsonb_typeof(p_reviewed->'targets') IS DISTINCT FROM 'array'
  OR jsonb_typeof(p_reviewed->'external_references') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'ADVISORY096_REVIEW_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('advisory096-fixed-legacy-batch',0));
 -- Coordinate with all existing writers and 095. No existing business table is written.
 FOR r IN SELECT n.nspname,c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE c.relkind IN ('r','p') AND NOT c.relispartition AND
   (n.nspname='public' OR n.nspname='auth' AND c.relname='users'
    OR n.nspname='storage' AND c.relname IN ('buckets','objects'))
  AND c.relname<>'advisory_matter_archives' ORDER BY n.nspname COLLATE "C",c.relname COLLATE "C"
 LOOP EXECUTE format('LOCK TABLE %I.%I IN SHARE MODE',r.nspname,r.relname); END LOOP;
 LOCK TABLE public.advisory_matter_archives IN EXCLUSIVE MODE;
 IF NOT coalesce(public.advisory086_admin(),false) THEN RAISE EXCEPTION 'ADVISORY_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM m.id FROM public.advisory_matters m WHERE m.matter_no=ANY(expected_numbers) ORDER BY m.id FOR UPDATE;
 SELECT public.advisory096_capture() INTO state;
 IF NOT coalesce((state->>'targets_exact')::boolean,false)
  OR state->'targets' IS DISTINCT FROM p_reviewed->'targets'
 THEN RAISE EXCEPTION 'ADVISORY096_IDENTITY_CHANGED'; END IF;
 IF NOT coalesce((state->>'legacy_origin_readable')::boolean,false)
  OR NOT coalesce((state->>'prior_archive_exact')::boolean,false)
  OR NOT coalesce((state->>'contract095_exact')::boolean,false)
  OR NOT coalesce((state->>'foundation_exact')::boolean,false)
 THEN RAISE EXCEPTION 'ADVISORY096_ACCEPTED_STATE_CHANGED'; END IF;
 FOR r IN SELECT unnest(ARRAY['rows_sha256','preserved_sha256','targets_sha256','prior_archives_sha256']) k LOOP
  IF coalesce(p_reviewed->>r.k,'') !~ '^[0-9a-f]{64}$' OR state->>r.k IS DISTINCT FROM p_reviewed->>r.k
  THEN RAISE EXCEPTION 'ADVISORY096_REVIEW_STALE'; END IF;
 END LOOP;
 IF state->'external_references' IS DISTINCT FROM p_reviewed->'external_references' THEN RAISE EXCEPTION 'ADVISORY096_REFERENCES_CHANGED'; END IF;
 SELECT count(*) INTO n FROM public.advisory_matter_archives a WHERE a.matter_no=ANY(expected_numbers);
 IF (SELECT count(*) FROM public.advisory_matter_archives)<>11+n THEN RAISE EXCEPTION 'ADVISORY096_UNEXPECTED_ARCHIVE'; END IF;
 IF n<>0 THEN
  IF n=9 AND NOT EXISTS(SELECT 1 FROM public.advisory_matter_archives a LEFT JOIN public.advisory_matters m ON m.id=a.matter_id
   WHERE a.matter_no=ANY(expected_numbers) AND (m.id IS NULL OR m.matter_no<>a.matter_no OR a.request_id<>p_request_id OR a.archived_by<>actor
    OR a.archive_reason<>btrim(p_reason) OR a.reviewed_baseline<>p_reviewed
    OR a.reviewed_matter_sha256<>encode(sha256(convert_to(to_jsonb(m)::text,'UTF8')),'hex')))
  THEN RETURN jsonb_build_object('archived',9,'request_id',p_request_id,'replayed',true); END IF;
  RAISE EXCEPTION 'ADVISORY096_RETRY_MISMATCH';
 END IF;
 IF EXISTS(SELECT 1 FROM public.advisory_matter_archives WHERE request_id=p_request_id) THEN RAISE EXCEPTION 'ADVISORY096_REQUEST_REUSED'; END IF;
 INSERT INTO public.advisory_matter_archives(matter_id,matter_no,archived_at,archived_by,archive_reason,request_id,reviewed_matter_sha256,reviewed_baseline)
 SELECT m.id,m.matter_no,moment,actor,btrim(p_reason),p_request_id,
  encode(sha256(convert_to(to_jsonb(m)::text,'UTF8')),'hex'),p_reviewed
 FROM public.advisory_matters m WHERE m.matter_no=ANY(expected_numbers);
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>9 THEN RAISE EXCEPTION 'ADVISORY096_TARGET_COUNT'; END IF;
 SELECT public.advisory096_capture() INTO after_state;
 IF state IS DISTINCT FROM after_state THEN RAISE EXCEPTION 'ADVISORY096_PRESERVATION_FAILED'; END IF;
 RETURN jsonb_build_object('archived',n,'request_id',p_request_id,'replayed',false);
END $fn$;

ALTER FUNCTION public.advisory096_capture() OWNER TO postgres;
ALTER FUNCTION public.advisory096_archive_legacy(uuid,text,jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.advisory096_capture(),public.advisory096_archive_legacy(uuid,text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.advisory096_archive_legacy(uuid,text,jsonb) TO authenticated;

DO $preserve$ DECLARE v_before096 jsonb; v_after096 jsonb; v_contract096 jsonb; BEGIN
 SELECT * INTO v_before096 FROM advisory096_before; WITH original AS (WITH targets AS (SELECT id,matter_no FROM public.advisory_matters WHERE matter_no=ANY(ARRAY['ADV-2026-004','ADV-2026-005','ADV-2026-006','ADV-2026-007','ADV-2026-008','ADV-2026-009','ADV-2026-010','ADV-2026-011','ADV-2026-012'])),
 rels AS MATERIALIZED (SELECT c.oid,n.nspname,c.relname,c.relkind FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','p') AND NOT c.relispartition
 AND (n.nspname='public' AND c.relname<>'advisory_matter_archives' OR n.nspname='auth' AND c.relname='users' OR n.nspname='storage' AND c.relname IN ('buckets','objects'))),
 rows AS MATERIALIZED (SELECT r.nspname||'.'||r.relname name,x.evidence::jsonb evidence FROM rels r CROSS JOIN LATERAL XMLTABLE('/table/row' PASSING query_to_xml(format(
 'SELECT jsonb_build_object(''count'',count(*),''sha256'',encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C"),''[]''::jsonb)::text,''UTF8'')),''hex''))::text evidence FROM %I.%I t',r.nspname,r.relname),false,false,'') COLUMNS evidence text PATH 'evidence') x),
 catalog AS MATERIALIZED (SELECT n.nspname||'.'||c.relname name,jsonb_build_object('kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,
 'view',CASE WHEN c.relkind='v' THEN pg_get_viewdef(c.oid,true) END,
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl::text,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(k.conname,pg_get_constraintdef(k.oid,true),k.convalidated) ORDER BY k.conname COLLATE "C"),'[]') FROM pg_constraint k WHERE k.conrelid=c.oid AND k.contype<>'n'),
 'indexes',(SELECT coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY ic.relname COLLATE "C"),'[]') FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),
 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p)-'schemaname'-'tablename' ORDER BY p.policyname COLLATE "C"),'[]') FROM pg_policies p WHERE p.schemaname=n.nspname AND p.tablename=c.relname),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname COLLATE "C"),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND t.tgname NOT LIKE 'advisory095_%')) evidence FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE c.relkind IN ('r','p','v','m','S') AND NOT c.relispartition AND (n.nspname='public' AND NOT (c.relname='advisory_matter_archives' OR c.relname IN ('advisory_operational_matters','advisory_operational_issues','advisory_operational_tasks','advisory_operational_time','advisory_operational_advice')) OR n.nspname='auth' AND c.relname='users' OR n.nspname='storage' AND c.relname IN ('objects','buckets'))),
 funcs AS MATERIALIZED (SELECT p.oid::regprocedure::text name,jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.proacl::text) evidence FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.prokind IN ('f','p') AND p.proname NOT LIKE 'advisory095_%' AND p.proname NOT LIKE 'advisory096_%' AND p.oid::regprocedure::text NOT IN ('advisory_control_read(uuid,jsonb)','advisory_control_section(uuid,text,integer,uuid)','advisory_overdue_work(uuid)','advisory_workflow_checks(uuid)')),
 target_rows AS MATERIALIZED (SELECT t.*,to_jsonb(m) facts FROM targets t LEFT JOIN public.advisory_matters m ON m.id=t.id AND m.matter_no=t.matter_no),
 tokens AS MATERIALIZED (SELECT array_agg(DISTINCT token) ids FROM (
 SELECT id::text token FROM targets UNION SELECT matter_no FROM targets
 UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_issues x JOIN targets t ON t.id=x.advisory_matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_issue_tasks x JOIN targets t ON t.id=x.advisory_matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_time_logs x JOIN targets t ON t.id=x.advisory_matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_advice_records x JOIN targets t ON t.id=x.advisory_matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_matter_control x JOIN targets t ON t.id=x.matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_matter_team x JOIN targets t ON t.id=x.matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_matter_stages x JOIN targets t ON t.id=x.matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_stage_visits x JOIN targets t ON t.id=x.matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_journey_snapshots x JOIN targets t ON t.id=x.matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_matter_activities x JOIN targets t ON t.id=x.matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_work_state_events x JOIN targets t ON t.id=x.matter_id
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_deliverables x JOIN targets t ON t.id=x.matter_id
 ) x WHERE token IS NOT NULL),
 ref_columns AS (SELECT n.nspname,c.relname,a.attname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped
 WHERE n.nspname='public' AND c.relkind IN ('r','p') AND NOT c.relispartition AND (c.relname LIKE 'finance_%' OR c.relname='cases' OR c.relname LIKE 'case_%') AND c.relname<>'case_audit_logs'
 AND (a.atttypid IN ('json'::regtype,'jsonb'::regtype) OR a.attname ~ '(advisory|matter|issue|task|source|origin|record|entity|object|target).*(id|ids|no|reference)$'
 OR EXISTS(SELECT 1 FROM pg_constraint k WHERE k.contype='f' AND k.conrelid=c.oid AND a.attnum=ANY(k.conkey) AND k.confrelid IN(SELECT to_regclass('public.'||x) FROM unnest(ARRAY['advisory_matters','advisory_issues','advisory_issue_tasks','advisory_time_logs','advisory_advice_records','advisory_matter_control','advisory_matter_team','advisory_matter_stages','advisory_stage_visits','advisory_journey_snapshots','advisory_matter_activities','advisory_work_state_events','advisory_deliverables']) x)))),
 refs AS MATERIALIZED (SELECT r.relname table_name,x.n FROM (SELECT nspname,relname,string_agg(format('EXISTS(SELECT 1 FROM unnest(%L::text[]) tok WHERE strpos(coalesce(r.%I::text,''''),tok)>0)',tokens.ids::text,attname),' OR ' ORDER BY attname) predicate FROM ref_columns CROSS JOIN tokens GROUP BY nspname,relname) r
 CROSS JOIN LATERAL XMLTABLE('/table/row' PASSING query_to_xml(format('SELECT count(*)::bigint n FROM %I.%I r WHERE %s',r.nspname,r.relname,r.predicate),false,false,'') COLUMNS n bigint PATH 'n') x WHERE x.n>0),
 raw AS (SELECT (SELECT jsonb_object_agg(name,evidence) FROM rows) rows,
 jsonb_build_object('relations',(SELECT jsonb_object_agg(name,evidence) FROM catalog),'functions',(SELECT jsonb_object_agg(name,evidence) FROM funcs),
 'roles',(SELECT jsonb_agg(jsonb_build_array(rolname,rolsuper,rolinherit,rolbypassrls) ORDER BY rolname COLLATE "C") FROM pg_roles),
 'members',(SELECT jsonb_agg(jsonb_build_array(roleid::regrole::text,member::regrole::text,admin_option) ORDER BY roleid::regrole::text COLLATE "C",member::regrole::text COLLATE "C") FROM pg_auth_members)) preserved,
 (SELECT jsonb_agg(jsonb_build_object('id',id,'matter_no',matter_no,'sha256',encode(sha256(convert_to((facts)::text,'UTF8')),'hex')) ORDER BY matter_no COLLATE "C") FROM target_rows) targets,
 (SELECT count(*)=9 AND bool_and(facts IS NOT NULL) FROM target_rows) AND (SELECT count(*)=9 FROM public.advisory_matters WHERE matter_no IN(SELECT matter_no FROM targets)) targets_exact)
 SELECT jsonb_build_object('rows_sha256',encode(sha256(convert_to((rows)::text,'UTF8')),'hex'),'preserved_sha256',encode(sha256(convert_to((preserved)::text,'UTF8')),'hex'),'targets_sha256',encode(sha256(convert_to((targets)::text,'UTF8')),'hex'),
 'row_fingerprints',rows,'targets',targets,'targets_exact',targets_exact,
 'protected_count',(SELECT count(*) FROM public.advisory_matters WHERE matter_no=ANY(ARRAY['ADV-2026-004','ADV-2026-005','ADV-2026-006','ADV-2026-007','ADV-2026-008','ADV-2026-009','ADV-2026-010','ADV-2026-011','ADV-2026-012'])),
 'external_references',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY table_name COLLATE "C"),'[]') FROM refs r),
 'reviewed_special_evidence',jsonb_build_object('time_023_minutes',(SELECT coalesce(sum(minutes),0) FROM public.advisory_time_logs WHERE advisory_matter_id='8cf4af68-18cd-415f-a56e-578e4ccaa2d1'::uuid),
 'snapshot_matters',(SELECT coalesce(jsonb_agg(m.matter_no ORDER BY m.matter_no COLLATE "C"),'[]') FROM public.advisory_journey_snapshots s JOIN public.advisory_matters m ON m.id=s.matter_id WHERE m.matter_no=ANY(ARRAY['ADV-2026-019','ADV-2026-020','ADV-2026-021','ADV-2026-022','ADV-2026-023'])),
 'audit_014_count',(SELECT count(*) FROM public.case_audit_logs a WHERE a.table_name LIKE 'advisory_%' AND a.record_id IN(
 SELECT '7583d780-9e98-4852-bf5a-98c40fbf8072' UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_issues x WHERE x.advisory_matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_issue_tasks x WHERE x.advisory_matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_time_logs x WHERE x.advisory_matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_advice_records x WHERE x.advisory_matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_matter_control x WHERE x.matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_matter_team x WHERE x.matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_matter_stages x WHERE x.matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_stage_visits x WHERE x.matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_journey_snapshots x WHERE x.matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_matter_activities x WHERE x.matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_work_state_events x WHERE x.matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid
UNION SELECT to_jsonb(x)->>'id' FROM public.advisory_deliverables x WHERE x.matter_id='7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid)))) FROM raw), prior(id,matter_no) AS (VALUES ('8f375864-0fb3-4d17-9e07-d4f6d76cf4fe'::uuid,'ADV-2026-013'),('7583d780-9e98-4852-bf5a-98c40fbf8072'::uuid,'ADV-2026-014'),('02e5ba61-af9b-4dc0-8729-9e334639b652'::uuid,'ADV-2026-015'),('c9aa7141-ed6a-4cdd-926a-ad261fb93dd6'::uuid,'ADV-2026-016'),('47bfb55e-3ac5-445c-b335-5d48417f793e'::uuid,'ADV-2026-017'),('7442060f-5a6b-4235-a826-597a6a53bb37'::uuid,'ADV-2026-018'),('b02ba4f6-ccc8-43df-91d1-9d584ef6a7e0'::uuid,'ADV-2026-019'),('6c717f2e-aff6-44af-9774-e910d7a61047'::uuid,'ADV-2026-020'),('35583652-f594-4d7b-8f6a-24991df14dad'::uuid,'ADV-2026-021'),('50221a99-f188-4f18-9017-b6f3302a5c2f'::uuid,'ADV-2026-022'),('8cf4af68-18cd-415f-a56e-578e4ccaa2d1'::uuid,'ADV-2026-023')),installed AS (SELECT jsonb_build_object('functions',(SELECT coalesce(jsonb_object_agg(signature,evidence),'{}') FROM (
 SELECT p.oid::regprocedure::text signature,jsonb_build_object('definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),
 'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'acl',p.proacl::text,
 'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')) evidence
 FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.prokind='f' AND
 (p.proname LIKE 'advisory095_%' OR p.oid::regprocedure::text IN ('advisory_control_read(uuid,jsonb)','advisory_control_section(uuid,text,integer,uuid)','advisory_overdue_work(uuid)','advisory_workflow_checks(uuid)'))) x),'relations',(SELECT coalesce(jsonb_object_agg(c.relname,jsonb_build_object('kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,
 'view',CASE WHEN c.relkind='v' THEN pg_get_viewdef(c.oid,true) END,
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,a.attacl::text,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_array(k.conname,pg_get_constraintdef(k.oid,true),k.convalidated) ORDER BY k.conname COLLATE "C"),'[]') FROM pg_constraint k WHERE k.conrelid=c.oid AND k.contype<>'n'),
 'indexes',(SELECT coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY ic.relname COLLATE "C"),'[]') FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),
 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p)-'schemaname'-'tablename' ORDER BY p.policyname COLLATE "C"),'[]') FROM pg_policies p WHERE p.schemaname=n.nspname AND p.tablename=c.relname),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_array(t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname COLLATE "C"),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal ))),'{}') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','v') AND (c.relname='advisory_matter_archives' OR c.relname IN ('advisory_operational_matters','advisory_operational_issues','advisory_operational_tasks','advisory_operational_time','advisory_operational_advice'))),
 'guards',(SELECT coalesce(jsonb_agg(jsonb_build_array(c.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid,true)) ORDER BY c.relname COLLATE "C",t.tgname COLLATE "C"),'[]') FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace='public'::regnamespace AND t.tgname LIKE 'advisory095_%' AND c.relname<>'advisory_matter_archives'))), foundation AS (WITH original AS (with prior as (WITH structure AS (WITH RECURSIVE
scope(name) AS (VALUES
 ('advisory_matters'), ('advisory_issues'), ('advisory_issue_tasks'),
 ('advisory_advice_records'), ('advisory_time_logs'), ('advisory_matter_counters'),
('advisory_matter_control'),('advisory_matter_team'),('advisory_matter_stages'),('advisory_stage_visits'),('advisory_work_state_events'),('advisory_matter_activities'),('advisory_deliverables'),('advisory_control_requests')
),
relations AS (
 SELECT c.*, n.nspname FROM scope s JOIN pg_class c ON c.oid=to_regclass('public.'||s.name)
 JOIN pg_namespace n ON n.oid=c.relnamespace
),
catalog AS (
 SELECT t.relname name,jsonb_build_object(
  'schema',t.nspname,'kind',t.relkind,'owner',pg_get_userbyid(t.relowner),
  'rls_enabled',t.relrowsecurity,'rls_forced',t.relforcerowsecurity,'acl',t.relacl::text,
  'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
    'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,
    'acl',a.attacl::text) ORDER BY a.attnum),'[]') FROM pg_attribute a
    LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
    WHERE a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped),
  'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.conname,'validated',c.convalidated,
    'definition',pg_get_constraintdef(c.oid,true)) ORDER BY c.conname COLLATE "C"),'[]') FROM pg_constraint c WHERE c.conrelid=t.oid AND c.contype<>'n'),
  'incoming_foreign_keys',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,
    'name',c.conname,'definition',pg_get_constraintdef(c.oid,true)) ORDER BY c.conrelid::regclass::text COLLATE "C",c.conname COLLATE "C"),'[]')
    FROM pg_constraint c WHERE c.confrelid=t.oid AND c.contype='f' AND c.conrelid NOT IN (select c2.oid from pg_class c2 join pg_namespace n2 on n2.oid=c2.relnamespace where n2.nspname='public' and c2.relname in ('advisory_journey_variants','advisory_journey_versions','advisory_journey_snapshots','advisory_journey_requests','advisory_matter_archives'))),
  'indexes',(SELECT coalesce(jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY i.indexrelid::regclass::text COLLATE "C"),'[]')
    FROM pg_index i WHERE i.indrelid=t.oid),
  'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('definition',pg_get_triggerdef(g.oid,true),'enabled',g.tgenabled)
    ORDER BY g.tgname COLLATE "C"),'[]') FROM pg_trigger g WHERE g.tgrelid=t.oid AND NOT g.tgisinternal AND g.tgname NOT LIKE 'advisory095_%'),
  'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,
    'roles',(SELECT jsonb_agg(CASE WHEN role_id=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_id) END ORDER BY role_id)
      FROM unnest(p.polroles) role_id),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid))
    ORDER BY p.polname COLLATE "C"),'[]') FROM pg_policy p WHERE p.polrelid=t.oid),
  'effective_grants_before_rls',(SELECT jsonb_object_agg(r.rolname,jsonb_build_object(
    'select',has_table_privilege(r.oid,t.oid,'SELECT'),'insert',has_table_privilege(r.oid,t.oid,'INSERT'),
    'update',has_table_privilege(r.oid,t.oid,'UPDATE'),'delete',has_table_privilege(r.oid,t.oid,'DELETE'),
    'truncate',has_table_privilege(r.oid,t.oid,'TRUNCATE'))) FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role'))
 ) evidence FROM relations t
), new_functions as (select p.oid::regprocedure::text name,jsonb_build_object('definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'acl',p.proacl::text,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')) evidence from pg_proc p where p.pronamespace='public'::regnamespace and (p.proname like 'advisory076_%' or p.proname in ('advisory_control_read','advisory_control_write','advisory_control_section','advisory_workflow_checks','advisory_overdue_work')))
 select jsonb_build_object('catalog',
 (select jsonb_object_agg(name,evidence) from catalog where name in ('advisory_matters','advisory_issues','advisory_issue_tasks','advisory_advice_records','advisory_time_logs','advisory_matter_counters','advisory_matter_control','advisory_matter_team','advisory_matter_stages','advisory_stage_visits','advisory_work_state_events','advisory_matter_activities','advisory_deliverables','advisory_control_requests')),
 'contract',jsonb_build_object('tables',(select jsonb_object_agg(name,evidence) from catalog where name in ('advisory_matter_control','advisory_matter_team','advisory_matter_stages','advisory_stage_visits','advisory_work_state_events','advisory_matter_activities','advisory_deliverables','advisory_control_requests')),
 'functions',(select jsonb_object_agg(name,evidence) from new_functions),
 'deltas',(select jsonb_object_agg(name,jsonb_build_object(
 'columns',(select coalesce(jsonb_agg(x order by n),'[]') from jsonb_array_elements(evidence->'columns') with ordinality a(x,n) where name='advisory_issue_tasks' and x->>'name' in ('advisory_matter_id','advisory_issue_id','assignee_user_id','stage_id') or name='advisory_time_logs' and x->>'name'='stage_id'),
